insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 1, 'ISIALA''s Scenario Builder run at seed 20260829 prints a Low case of 48.7439 million USD under the label P90. Read with the Suite''s definition sentence, what does that label claim?', '["That 90 percent of the 1000 sampled NPVs fall below 48.7439 million USD, the way a 90th percentile is read in ordinary arithmetic.", "That 90 percent of the 1000 sampled NPVs meet or exceed 48.7439 million USD, which is why P90 is the smallest of the three cases.", "That 48.7439 million USD is a floor for the field: with 90 percent confidence no sampled iteration returns an NPV below it.", "That the deterministic NPV of 81.0464 million USD has a 90 percent chance of landing above 48.7439 million USD once drilled."]'::jsonb, 1, 'The definition reads "P90 means a 90% probability the actual quantity meets or exceeds this value, per SPE PRMS." It is no floor: the lowest of the 1000 NPVs is 16.3054.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 2, 'Which engine key does ISIALA''s Low case card read, and why?', '["The `p90` key, because a P90 label and a `p90` key name the same position in the sorted sample of 1000 NPVs.", "The `p50` key less half the spread, because a Low case is built from the Best case and the width of the run.", "The `p10` key, but only because the panel sorts the NPVs from highest to lowest before it reads any position.", "The `p10` key: the value with 10 percent of the sorted NPVs below it is the value 90 percent of them meet or exceed."]'::jsonb, 3, 'The engine returns `p10`, `p50` and `p90` as plain percentiles of NPVs sorted low to high, so the Low case P90 reads `p10` at 48.7439 and the High case P10 reads `p90` at 109.8980.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 3, 'Before EC3-0, what did the Scenario Builder''s card headed "P90 (Conservative)" show for ISIALA?', '["109.8980 million USD from the `p90` key, a value only 10 percent of the sample meets or exceeds.", "48.7439 million USD from the `p10` key, so the number on the card was cautious and only its word needed changing.", "81.1835 million USD from the `p50` key, because the old panel treated the median as the conservative reading of a run.", "-72.1531 million USD, the scenario Low, which the old panel copied across from generateScenarios into its first card."]'::jsonb, 0, 'The old panel printed the `p90` key under "P90 (Conservative)" and the `p10` key under "P10 (Optimistic)", so the card called conservative held the larger number, 109.8980.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 4, 'A report lists ISIALA''s NPV cases as P90 109.8980, P50 81.1835 and P10 48.7439. What does the convention module''s gate helper make of it?', '["It passes the set, because the convention leaves the display order of the three cases to the author.", "It passes the set as a correct listing for a quantity where more is worse, such as a breakeven price, where the labels run the other way.", "It flags the set: under exceedance P90 must be at or below P50, and this P90 is larger, so the keys were printed as labels.", "It passes the set as a reseeded run whose draws happened to reverse the order of the three cases without any error in the labels."]'::jsonb, 2, 'The helper flags any case set where the P90 exceeds the P50 or the P50 exceeds the P10. A breakeven price takes no P-label at all, so reading the reversed set as a price listing is the second mistake, not a rescue.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 5, 'ISIALA''s breakeven run gives a 90th percentile of breakeven price of 85.5912 USD per bbl. Why does the Suite refuse to print a P-label beside it?', '["The breakeven engine returns no keys named `p10`, `p50` or `p90`, so the panel has nothing it could map to a label.", "A breakeven price is a single deterministic solve rather than a sample, so no percentile of it exists to carry a label.", "A P-label is defined only on a sample with no iterations excluded, and a breakeven run excludes some of its iterations.", "More price is worse, so an exceedance label would name 62.1713 to one reader and 85.5912 to another, and the convention drops the label."]'::jsonb, 3, 'The engine does return `p10`, `p50` and `p90` on 5000 iterations with none excluded; they are plain percentiles of a price. The refusal is about direction: the same label would point at both ends of the band.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 6, 'A report puts the exceedance label for 90 percent on ISIALA''s breakeven price. Read strictly with the definition sentence, which value does that label name?', '["85.5912 USD per bbl, since on a price the exceedance reading and the 90th percentile reading always agree with each other.", "62.1713 USD per bbl, the price 90 percent of iterations meet or exceed, which is the comfortable end.", "73.3297 USD per bbl, since a label on a quantity where more is worse collapses to the median of the breakeven sample.", "71.6277 USD per bbl, the base case at the stated medians, since the label attaches to the one solve that was not drawn."]'::jsonb, 1, 'Exceedance points at 62.1713 and the arithmetic habit points at 85.5912, the two ends of the band, which is exactly why a price is quoted as 10th percentile, median and 90th percentile.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 7, 'A board slide shows ISIALA''s scenario Low of -72.1531 million USD under a P90 heading. What is wrong with it?', '["It is one deterministic corner from generateScenarios, below all 1000 sampled NPVs, while the Low case P90 is 48.7439.", "Nothing: the scenario Low and the Low case P90 are two computations of the same position in the distribution of NPV.", "Only its label: a scenario Low is the pessimistic case, so it should carry P10, the label for the pessimistic end of a run.", "Only a missing seed: it is the Low case at another seed, so it belongs under the P90 heading once that seed is written beside it."]'::jsonb, 0, 'Under a P90 heading, -72.1531 tells the board there is a 90 percent chance of doing better, yet the lowest sampled NPV is 16.3054 and no iteration came near it. Relabelling it P10 would repeat the swap, since P10 is the High case label.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 8, 'ISIALA''s Scenario Builder run reports an EMV of 80.1707 million USD beside a Best case P50 of 81.1835. What is the EMV?', '["Another name for the Best case P50, printed from the same sorted position and rounded differently by the panel.", "The median read by the floor rule instead of the averaging rule, which is why it differs from the Best case card.", "The plain mean of the 1000 NPVs, which is not a case, takes no P-label, and sits below both the Best case and the deterministic 81.0464.", "The deterministic NPV recomputed at the sample''s average price, capex and reserves after all 1000 draws are made."]'::jsonb, 2, 'The EMV averages every NPV and the P50 reads the middle of the sorted sample; the floor rule''s median is 81.1952, above the card rather than below it.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 9, 'A low NPV case needs one end of each input belief. Which end of capex and which end of efficiency does it take?', '["The 10th percentile of both, because a low case always takes the 10th percentile of every variable in the model.", "The 90th percentile of capex and the 10th percentile of efficiency, because more capex hurts the NPV and more efficiency helps it.", "The 90th percentile of both, since the case is a P90 and its inputs inherit the number printed in that case''s label.", "The 10th percentile of capex and the 90th percentile of efficiency, since the smaller capex figure is the one planners treat as conservative."]'::jsonb, 1, 'The convention module picks a parameter''s percentile from whether more of it helps the outcome, which is why it writes "10th percentile of capex" and never a P-label on an input.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 10, 'A partner''s sheet gives ISIALA''s capex beliefs under P-labels, and the analyst must type them into the Breakeven Analyzer''s 10th, median and 90th percentile fields. What can go wrong?', '["Nothing, since for capex the exceedance label and the 90th percentile both name 220, because more capex is worse for the project.", "The fit refuses input that arrives under P-labels and clamps to the most left-skewed triangular it can build from the three values.", "The labels force the values to be read as minimum, mode and maximum, so the fit returns 164.4914, 182.5834 and 203.2668 at 0.1, 0.5 and 0.9.", "The label for ninety names 150 under exceedance and 220 under the arithmetic habit, so a guess can swap the ends of the fit."]'::jsonb, 3, 'Parameters take percentile words precisely because a P-label on an input carries no direction; the sheet''s labels are the mistake the question examines. The endpoints reading is a different error with its own vanished tails.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 11, 'ISIALA''s Low case P90 of 48.7439 says 90 percent of outcomes meet or exceed it. Ninety percent of what, exactly?', '["Of this model''s 1000 draws, which treat every year and variable as independent and never sample opex, royalty or tax.", "Of every outcome the field could deliver, because the label follows SPE PRMS and PRMS probabilities describe the field itself.", "Of the outcomes across every seed the engine could be run at, since the default seed 20260829 stands in for all of them.", "Of the three generateScenarios corners, as if the P90 weighted the Low, Base and High cases."]'::jsonb, 0, 'A P90 describes the sample the model drew and nothing more; with no correlation and no opex, royalty or tax uncertainty, 90 percent is conditional on those choices. Seed 43 moves the Best case to 79.0624.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 12, 'Why did the old Scenario Builder panel look right at a glance even while its two outer cards were swapped?', '["The old panel sorted NPVs from highest to lowest, so the numbers were in the right places and only the words were wrong.", "The old generator was unseeded, so testers never saw the same pair of outer numbers twice and could not compare them.", "The `p50` key is the Best case P50 under either reading, so the middle card showed 81.1835 before and after the repair.", "The swap touched only the Breakeven Analyzer''s cards, which the Scenario Builder does not show beside its three cases."]'::jsonb, 2, 'Printing a key as a P-label flips `p10` and `p90` but leaves `p50` untouched, and a panel whose middle number is right looks right.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 13, 'A saved slide from before EC3-0 shows a "P90 (Conservative)" card for some field. What can be recovered from it?', '["The whole sample, by rerunning at the default seed 20260829, which reproduces every run made by the old engine on those inputs.", "Its direction: the number is a High case, the value 10 percent of that run met or exceeded, but the sample cannot be rebuilt.", "Nothing at all, since the old card mixed keys from two separate runs and neither number describes any case of the field.", "The Low case, by exchanging the slide''s two outer numbers and keeping the old words so the slide still matches its notes."]'::jsonb, 1, 'The old engine called an unseeded generator, so a past run cannot be repeated; do not expect it to match 109.8980. Only the label can be corrected, from Conservative to High case P10.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 14, 'EC3-0 relabelled the Scenario Builder''s cards and seeded its run. Which of these did the repair leave exactly as it was?', '["The uncertainty the model omits: opex, royalty and tax are still never sampled in any iteration.", "The mapping from keys to cases, which still prints the `p90` key under the Low case so that existing callers keep working.", "The reproducibility of a run, since the default seed 20260829 repeats a sample only within one browser session.", "The display order, which still shows the High case first as the old panel did."]'::jsonb, 0, 'The keys stayed for existing callers, but the panel now maps them through `lib/conventions/percentile.js`, shows low to high and draws from mulberry32. Nothing in the fix adds opex, royalty or tax to 48.7439.'),
  ('uncertainty', 'advanced', 'module', 'm01-one-meaning-of-a-p-label', 15, 'One proposed fix for the swap was to exchange the two outer numbers and keep the words "Conservative" and "Optimistic". Why did the convention reject that?', '["Exchanging the numbers would break existing callers, because the `p90` key would then have to hold the Low case value.", "The words were never on the Scenario Builder; they came from the Breakeven Analyzer''s cards, which is where the swap really sat.", "Conservative and optimistic already mean exactly what P90 and P10 mean, so keeping them would only print each label twice.", "Those words send readers hunting for a cautious card on every quantity, and on a breakeven price the high end, 85.5912, is the risky one."]'::jsonb, 3, 'The convention names cases Low, Best and High with exceedance labels on outcomes, and a price takes percentile words: ISIALA''s 90th percentile of breakeven price is 85.5912 USD per bbl.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 1, 'At the app''s settings, how is ISIALA''s 2027 oil volume of 1606000.0000 bbl drawn in one Scenario Builder iteration?', '["From a triangular peaking at the base volume, with tails reaching past 0.8 and 1.2 times it the way a fitted belief does.", "From a normal centred on the base whose 10th and 90th percentile sit at 0.8 and 1.2 times it, so some draws land outside.", "Uniformly between 0.8 and 1.2 times the base, every point equally likely and nothing outside.", "As one multiplier between 0.8 and 1.2 drawn for the iteration and applied to that year and every later year''s volume."]'::jsonb, 2, 'Each value v with a range r is drawn uniformly on [v(1 - r), v(1 + r)], one draw per year per array; plus or minus 20 percent is a width, with no mode and hard edges.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 2, 'The first draw of mulberry32(20260829) is 0.936239. Where does it land in ISIALA''s Scenario Builder run?', '["On the 2027 oil volume, near the top of its range, because oil volume comes first in the draw order.", "On the 2027 oil price, because price is the headline range and the draw order starts with the prices before any volume.", "On capex, as 226.5205 million USD, which is the value that same draw gives in the Breakeven Analyzer at that seed.", "On all three ranges at once, since one draw per iteration scales the price, the capex and the reserves together."]'::jsonb, 0, 'The order is oil volume, gas volume, oil price, gas price, capex, one draw per year. 226.5205 is what the draw becomes in the other engine, through a triangular inverse CDF.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 3, 'Why does the lowest of ISIALA''s 1000 sampled NPVs, 16.3054, sit so far above the scenario Low of -72.1531?', '["The Monte Carlo discounts at year end while generateScenarios discounts mid-year, which lifts every sampled NPV above the corner case.", "One thousand iterations are too few to reach the tail, and a run of 20000 iterations would carry its lowest NPV down to -72.1531.", "The uniform range is clipped at the base value on its downside, so the sampled prices and volumes can only move upward from it.", "Every year and variable is drawn on its own, so yearly draws partly cancel and no iteration pushes everything to its bad end together."]'::jsonb, 3, 'The scenario moves price and production to 0.8 times base in every year at once; the Monte Carlo''s Low case P90 of 48.7439 and its minimum both reflect independent draws that never line up that way.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 4, 'An analyst reads plus or minus 20 percent on price as "the price could stay 20 percent lower for the life of the field". What does the range actually do?', '["Exactly what the analyst says: one multiplier sets the whole life, which is why the Low case P90 sits at 48.7439 million USD.", "It draws each year''s price on its own inside 0.8 to 1.2 times base; a price that stays low is a scenario and must be built as one.", "It states a percentile belief, so 20 percent of the iterations price below 0.8 times base and the rest price above it.", "It draws price once per iteration and capex and reserves once per year, so price is the one input that can stay low for life."]'::jsonb, 1, 'Independence across years is why the Low case P90 of 48.7439 sits far above the scenario Low of -72.1531: the range is applied to each year separately.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 5, 'Which arrays does the Scenario Builder''s range called reserves scale?', '["A total recoverable volume, rescaled once per iteration and then declined at the base ratio of 0.880000 year on year.", "Oil volume alone, because ISIALA''s gas volume is 0 and the engine skips a zero array without consuming its draws.", "Oil volume and gas volume, each year drawn on its own, with no total recoverable volume in the draw.", "Oil volume together with the variable opex computed from it, so the costs follow the barrels the iteration sampled."]'::jsonb, 2, 'A draw low in 2027 and high in 2028 gives a profile that rises, so the sampled profile keeps no decline and no believed total; the gas draws are still consumed because the range is not falsy.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 6, 'An iteration draws ISIALA''s 2027 oil volume near 0.8 times base. What variable opex does 2027 carry in that iteration?', '["About 0.8 times 20.8780 million USD, since variable opex is volume times 13 USD/bbl.", "2.5000 million USD, the fixed opex alone, since a sampled volume replaces the variable part of the cost with nothing.", "Whatever the opex range draws for that year, since opex is sampled in the fifth position of the order beside capex.", "20.8780 million USD, the base value, because variable opex was fixed at expansion and does not follow the draw."]'::jsonb, 3, 'The variable opex array was computed from base volumes when the quick inputs were expanded, and the Monte Carlo never touches it, so a low-volume iteration still pays the full 20.8780.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 7, 'A reader calls the spread from ISIALA''s Low case P90 of 48.7439 to its High case P10 of 109.8980 "the uncertainty in ISIALA". What does that spread leave out?', '["Every input never sampled, opex, royalty, tax, decline and discount rate among them; fixed opex alone moves the sweep''s NPV from 85.3696 to 76.7233.", "Nothing among the costs, since the capex range scales fixed opex and variable opex along with capex in every year.", "Only the correlation of opex with price, since opex, royalty and tax are sampled each year but drawn independently.", "Only the gas price, which ISIALA never sells, so for an oil field the three ranges already cover every input."]'::jsonb, 0, 'Price, capex and reserves are the only ranges; the sensitivity sweep scales fixed opex by 0.7 and 1.3 and the scenario Low by 1.2, but the Monte Carlo leaves it alone.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 8, 'In the published case mc_seed3_price_only the reserves and capex ranges are falsy. What happens to the stream of draws?', '["The falsy ranges still consume their draws and throw them away, so the price draws keep the positions they have in a full run.", "Those ranges consume no draws, so the price draws take stream positions the volume draws would otherwise have used.", "The engine refuses to sample with any falsy range and returns the deterministic NPV in every iteration instead.", "The falsy ranges fall back to the app''s plus or minus 20 percent, so the case samples all three ranges after all."]'::jsonb, 1, 'A falsy range consumes nothing; switching one range between zero and nonzero at the same seed moves every later draw onto a different value, which is why the seed alone does not fix the sample.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 9, 'ISIALA''s Best case P50 is 81.1835 million USD at seed 20260829 and 79.0624 at seed 43, with everything else the same. Which one is accurate?', '["81.1835, because it sits closer to the deterministic 81.0464 million USD, and a good sample should centre on the base case.", "81.1835, because the engine''s goldens were validated at the default seed.", "79.0624, because a seed the analyst picks avoids whatever bias a developer built into the seed chosen as default.", "Neither is more correct: each is one sample of 1000, and the gap shows how much a single seed hides."]'::jsonb, 3, 'A seed buys reproducibility, not accuracy. Reporting 81.1835 because it is nearer 81.0464 is seed shopping: fix the seed before the first run and treat the gap as part of the uncertainty.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 10, 'At seed 20260829 the Breakeven Analyzer''s first draw is also 0.936239. Can its sample be compared, iteration by iteration, with the Scenario Builder''s at that seed?', '["Yes, since a shared seed pairs each iteration''s price in one app with the same iteration''s capex in the other app.", "Yes for the first iteration only, because the two engines take the same draws until the Scenario Builder needs more of them.", "No: there the draw becomes a capex of 226.5205 million USD, three draws per iteration, so the two samples are unrelated.", "No, because the Breakeven Analyzer ignores its seed unless the run is set to exactly 5000 iterations."]'::jsonb, 2, 'The breakeven engine takes capex, opex and efficiency through a triangular inverse CDF; the Scenario Builder spends that draw on the 2027 oil volume. One seed, two unrelated samples.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 11, 'At 5000 iterations ISIALA''s median breakeven price across seeds 1 to 10 spans 72.6338 to 73.1287, and the default seed gives 73.3297. Should the default seed be distrusted?', '["No: it drew a sample near one edge of what the model produces, and every run at that seed will faithfully repeat that edge.", "Yes: a default that falls outside the span of ten other seeds is biased and should be replaced by seed 1 for reporting.", "No: the default seed is the accurate one, and seeds 1 to 10 all sit low because small seeds give correlated streams.", "Yes: that run must have excluded iterations the other ten seeds kept, which is what moved its median above theirs."]'::jsonb, 0, 'ISIALA''s breakeven run excludes none. Reproducible is all a seed guarantees; the ten medians alone span 0.4949 USD per bbl.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 12, 'ISIALA''s tallest histogram bin is the ninth, holding 114, while the Best case P50 of 81.1835 falls in the tenth, holding 94, and the eleventh and twelfth hold 96 and 111. How should that dip be read?', '["As the mode, the most likely NPV, sitting one bin below the median through skew.", "As binning noise in one sample of 1000; a slightly different width would merge or split the two peaks.", "As two populations of NPV, one for each capex year, so the model really has two most likely values and a trough between.", "As the effect of rounding the bin width of 6.6524 million USD, which the engine would remove at 20 bins of density."]'::jsonb, 1, 'The model has one field, three uniform ranges and no switch between regimes, so nothing in it can make two peaks; the tallest bin is not the most likely NPV.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 13, 'An analyst lays ISIALA''s histogram at seed 43 over the one at seed 20260829 and compares the counts bin by bin. Why is that comparison invalid?', '["It is valid, because both runs use 20 bins of the same fixed width of 6.6524 million USD, starting from the same edge.", "It is valid once each count is divided by 1000 to turn it into a share of the run.", "It is invalid only for the first and last bins, which move with the extremes while the inner eighteen bins stay put.", "Each run''s bins span its own lowest to highest NPV, so every count describes a different interval."]'::jsonb, 3, 'The width is the sample''s range divided by 20: 6.6524 comes from 16.3054 and 149.3540 at the default seed and describes no other sample.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 14, 'ISIALA''s S-curve at 1000 iterations has 50 points, the first at probability 0.0000 and the last at 98.0000. What does the chart never draw?', '["The sorted values above the last point, including the highest NPV of 149.3540, so its right end is not the maximum.", "Nothing: the point at 98.0000 is the highest NPV, placed there because the axis leaves two points of headroom at the top.", "The lowest values, because the curve starts at the first multiple of 20 and so leaves out the lowest NPV of 16.3054.", "The middle of the sample, because keeping one point in 20 retains the tails and thins out the values near the median."]'::jsonb, 0, 'The step is 1000 divided by 50, one point every 20 sorted values, and the sorted value at index i sits at i divided by n times 100, so the last kept index reads 98.0000.'),
  ('uncertainty', 'advanced', 'module', 'm02-the-scenario-builder-monte-carlo', 15, 'The S-curve point at height 10 is 48.8335 million USD, but the Low case card shows 48.7439. Which one is wrong?', '["The card, because the S-curve plots the raw sample while the `p10` key is rounded for display on the panel.", "The curve, because its axis shows exceedance, so the point at height 10 is really the High case P10 and belongs on another card.", "Neither: the curve plots the single sorted value at index 100, while the card''s `p10` key averages two neighbours.", "The curve, which is drawn from a cached sample of an earlier seed and so lags the card by one run of the engine."]'::jsonb, 2, 'The axis counts the share below a value, so height 10 is the Low case P90''s region; the curve uses a different percentile rule from the cards, and 81.1952 against 81.1835 at the middle is the same effect.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 1, 'On ISIALA''s 1000 Scenario Builder NPVs, which branch of the `lib/stats` quantile rule gives the three cases at q of 0.1, 0.5 and 0.9?', '["The single-value branch at every row, because a whole position needs no averaging and the rule simply reads the value there.", "The averaging branch at every row, because n x q is 100, 500 and 900, all whole on an even length.", "Averaging at the median only, with the Low case and High case read as single values because the tails of a sample are sparse.", "The odd-length branch, taking the value after the position at every row, because 1000 sorted values have no middle pair."]'::jsonb, 1, 'The rule averages the value at position n x q with the next one when n x q is whole and n is even, so 48.7439, 81.1835 and 109.8980 are all averages.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 2, 'An analyst searches ISIALA''s exported sorted `allValues` for the Low case card''s 48.7439 million USD and finds nothing. What should they conclude?', '["The card is stale, left over from an unseeded run made before EC3-0 that the current export does not contain.", "The export is rounded to four decimals while the card holds full precision, so the search fails on rounding alone.", "The card reads the `p90` key, so the value to look for in the export is 109.8980 and the search was aimed at the wrong end.", "The card is right: it is the midpoint of two neighbouring NPVs, the upper being 48.8335, so no iteration produced it."]'::jsonb, 3, 'Under its own rule the averaged card value is not a member of the sample; the floor rule''s 48.8335 is the upper neighbour, and 81.1835 and 109.8980 are equally absent.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 3, 'The Breakeven Analyzer reads `sorted[min(n - 1, floor(q n))]`. On ISIALA''s 5000 iterations, what is the 90th percentile of breakeven price, and why does it match the insight sentence?', '["Index 4500, 85.5912 USD per bbl, with exactly 4500 iterations below it: a 90 percent chance the breakeven price is below that.", "The value one position below index 4500, since the floor rounds the answer itself down to the lower neighbour of a whole position.", "The mean of the two values either side of index 4500, since 5000 x 0.9 is whole on an even length and every rule then averages.", "Index 500 counted down from the top of the sort, which gives 62.1713 because a breakeven price is read under the exceedance meaning."]'::jsonb, 0, 'The floor rule has one branch and always returns a member of the sample; none of ISIALA''s 5000 iterations is excluded, so n is 5000 and the index is 4500.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 4, 'Applied to ISIALA''s 1000 NPVs, the averaging rule minus the floor rule is -0.0896, -0.0116 and -0.0056 at the three cases. Why is every difference negative?', '["The floor rule rounds its answer down and so should read lower, and the negative sign shows the export was sorted in descending order instead.", "The averaging rule folds the sample mean of 80.1707 million USD into each reading, which drags every one of its three cases downward below the floor.", "On a whole n x q the averaging rule blends the value at the index with the one before it, and the floor rule takes the upper of the two.", "Seed noise: the floor rule was applied to a second, independent draw of 1000 NPVs that happened to sit slightly higher than the first draw."]'::jsonb, 2, 'On this sample the floor rule cannot sit below the averaging rule, because the midpoint of two sorted values never exceeds the upper one; 48.8335 against 48.7439 is the largest gap.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 5, 'A reviewer wants the floor rule for ISIALA''s NPV Low case because "floor" sounds cautious. What is wrong with that reasoning?', '["Nothing: flooring rounds the NPV itself down to the lower of two neighbours, which is the cautious choice for a Low case.", "The floor acts on the index, so it takes the upper neighbour, 48.8335 against 48.7439, leaning the Low case toward the good end.", "It holds for the Low case alone, since the floor lowers the value at q of 0.1 and raises it at q of 0.9, so only the High case suffers.", "The choice is irrelevant, because both rules return exactly 48.7439 whenever the iteration count is an even number."]'::jsonb, 1, 'On a breakeven price the floor leans a percentile towards the risky end; on an NPV it leans towards the good end, so a reader who assumes it is cautious has the direction backwards.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 6, 'Why does a one-branch floor rule suit the Breakeven Analyzer in particular?', '["A breakeven sample always holds exactly 5000 values, so the averaging branch could never be reached and there is nothing to choose.", "Prices are quoted to four decimals, and averaging two neighbouring prices would produce a value finer than the screen can print.", "The floor rule reads the lower of two neighbours, which gives the cautious, lower price that a breakeven report is meant to show.", "Iterations that cannot break even below 500 USD per bbl are excluded before the sort, so n is whatever survives and one branch copes with any count."]'::jsonb, 3, 'In the published mc_with_unreachable, 55 of 120 iterations are excluded, and the 10th percentile of breakeven price, 397.3404, is still a price one real iteration produced.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 7, 'Two Scenario Builder runs of one field differ only in iteration count: one is even with n x q whole at every row, the other is odd. What changes in how their cards are read?', '["The even run averages two sorted values per case, the odd run never averages and reads single sorted values, and the panel never says which branch was used.", "Nothing changes between the two runs on the panel, because the rule averages two sorted values whenever n x q is a whole number, whatever the parity of the iteration count.", "The odd run interpolates across three neighbouring sorted values to build a middle, since an odd count has no middle pair.", "The odd run''s cards are withheld, because the rule refuses a sample it cannot split into two halves of equal length."]'::jsonb, 0, 'The branch depends on the count, so two runs of one field can read their cases by different rules with nothing on the panel to show it; name the rule before comparing two numbers.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 8, 'ISIALA''s median NPV is 81.1835 by the averaging rule and 81.1952 by the floor rule, a difference of -0.0116. What is that gap made of?', '["The distance between the sample mean and the median, which the averaging rule quietly blends into its reading of the middle.", "A rounding artefact from printing money to four decimals, which vanishes once both medians are carried at full precision.", "Exactly half the spacing between the two middle neighbours: one rule returns their midpoint and the other the upper one.", "Seed noise between two runs at seed 20260829, since each rule sorts its own freshly drawn sample of 1000 NPVs."]'::jsonb, 2, 'The sample is sorted once and both rules read it; the Best case P50 card shows the averaging rule''s 81.1835, and the EMV of 80.1707 is a separate quantity altogether.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 9, 'Does the gap between the two percentile rules on ISIALA''s 1000 NPVs grow toward the tails of the sample?', '["Yes: tails are sparse, so the spacing always widens away from the median, and the High case gap is therefore the largest of the three.", "Yes, on the low side only: the gap grows toward small NPVs and shrinks toward large ones on every sample the engine draws.", "No: the gap is the same at every row, because the rules differ by a fixed half step of one sorted position everywhere.", "No: it is half a random spacing, -0.0896 at the Low case, -0.0116 at the median and -0.0056 at the High case, the smallest."]'::jsonb, 3, 'The gap is half the space between two neighbouring sorted values, and that space is as random as the sample, so no rule of thumb places the largest gap in the tails.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 10, 'Rank these three gaps on ISIALA from smallest to largest: the rule difference at the median, the deterministic case against the medians, and seed 43''s change to the Best case P50.', '["Seed 43''s change first, since both runs share 1000 iterations and the same ranges, then the rule difference, then the deterministic gap.", "The rule difference of -0.0116, then the deterministic 81.0464 below both medians, then seed 43 moving the Best case to 79.0624.", "The deterministic gap first, since a Best case P50 is built to centre on the base case, then the rule difference, then the seed 43 change.", "All three agree to the second decimal, so none of them should be preferred when a Best case P50 is quoted in a report."]'::jsonb, 1, 'The choice of rule changes nothing about the sample and is by far the smallest gap; the seed moves the whole-number part, so arguing over the rule settles nothing while the seed is uncontrolled.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 11, 'ISIALA''s median breakeven price is 73.3297 USD per bbl and its base case at the stated medians is 71.6277. Is that the same kind of gap as the NPV''s 81.1835 against 81.1952?', '["No: it compares a different quantity from a different engine, a sample of 5000 triangular draws against one solve, and neither price takes a P-label.", "Yes: 71.6277 is the median read by the floor rule and 73.3297 the median read by the averaging rule on the same breakeven sample.", "Yes: both are rule gaps, and the price gap is the larger one simply because 5000 is a bigger even count than 1000.", "No: 71.6277 is the price''s Best case P50, which the convention allows a breakeven to carry when it comes from a base case solve."]'::jsonb, 0, 'The base case is a single solve at the stated medians and is not a percentile of the sample; a price is quoted as 10th percentile, median and 90th percentile, so calling 71.6277 a Best case P50 puts a P-label on a price, and that is itself the error.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 12, 'A report sets ISIALA''s median breakeven price of 73.3297 USD per bbl against a hurdle a few cents away. What is wrong with the comparison?', '["Nothing, since a seeded engine reproduces 73.3297 exactly, and a number that reproduces is precise to every decimal it prints.", "Only the percentile rule: the floor rule reads one real iteration, so its fourth decimal is exact where an averaged one would not be.", "The hurdle has to be discounted mid-year before any comparison is made, and after that a few cents can be resolved safely.", "Seeds 1 to 10 alone move the median across 0.4949 USD per bbl, so the fourth decimal is print format and the comparison is noise."]'::jsonb, 3, 'The engine prints prices to four decimals because it always does; the ten seeds already disagree in the first decimal place, so a report should quote the spread beside 73.3297.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 13, 'At the default seed ISIALA''s median breakeven price reads 72.7058, 72.9806, 72.9245, 73.3297 and 73.0302 at 100, 500, 1000, 5000 and 20000 iterations. What does that sequence show?', '["Steady convergence from below, so the 20000 iteration median of 73.0302 is the true median of the model to four decimals.", "A defect at 5000 iterations, where the stream of the default seed starts repeating and inflates that run''s median.", "More iterations shrink the typical wobble but promise nothing for one run: the 5000 median sits further from the 20000 value than the 1000 median does.", "That 100 iterations is enough, since its median of 72.7058 already lies inside the span the ten seeds give at 5000."]'::jsonb, 2, 'The median rises, falls, rises and falls again; the 20000 run is one more sample from one seed, and the engine has no convergence check to say otherwise.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 14, 'Against ISIALA''s ten seeds at 5000 iterations, where do the default seed''s 10th percentile of breakeven price, 62.1713, and its median, 73.3297, sit?', '["Both outside the ten seeds'' spans, which shows the default seed shifts the whole breakeven sample upward.", "The 10th percentile inside the span from 62.0081 to 62.4650, the median above the highest of the ten medians, 73.1287.", "Both inside the ten seeds'' spans, because the default seed was chosen to sit at the centre of the model''s range of outcomes.", "The median inside its span and the 10th percentile below its span, since the tail of any sample always wobbles more than its middle."]'::jsonb, 1, 'The two percentiles do not move together, as seed 3''s high 10th percentile of 62.4650 beside a low median of 72.8255 also shows; being the default makes a seed reproducible, not typical.'),
  ('uncertainty', 'advanced', 'module', 'm03-two-percentile-rules', 15, 'What does either engine report about how far one of its percentiles would move under another seed or iteration count?', '["A standard error beside every percentile, which is why the breakeven insight rounds its median to 73.33 per barrel and no further.", "A warning on the panel whenever a percentile moves between seeds by more than the rounding it is printed to.", "Nothing: no confidence interval, no standard error and no convergence check, so the spread has to be run and quoted by hand.", "A convergence check that stops the run once the median settles, which is how the default count of iterations was originally set."]'::jsonb, 2, 'The only way to see the wobble is several seeds at the iteration count you mean to report, with the spread printed beside the number; the ten seeds'' 10th percentiles span 0.4569 and their medians 0.4949.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 1, 'ISIALA is run through the repaired Scenario Builder Monte Carlo with the price, capex and reserves ranges all at zero, for 30 iterations. What comes back?', '["A TypeError from the histogram, because finding S4 was recorded in the oracle findings and left for the owner rather than repaired before the course.", "Three cases that differ in the fourth decimal, because the seeded generator still draws a value for every year even when the range it scales is zero.", "The deterministic NPV of 81.0464 million USD in all three cases and the emv, with bin 0 of the histogram holding 30 of 30 iterations.", "An empty histogram and three null cases, since a run with no spread has nothing to sort and the engine declines to report a percentile of one value."]'::jsonb, 2, 'EC3-0 repaired S4: every iteration is the base case, so the Low case P90, the Best case P50, the High case P10, the emv and the deterministic NPV all read 81.0464.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 2, 'Why did the Scenario Builder as published throw an error when every range was zero?', '["The histogram''s bin width was zero, so each value''s bin index came out as zero over zero, which is not a number, and counting into the bin at that index threw a TypeError.", "The uniform draw on the interval from v(1 - r) to v(1 + r) collapses to one point at r of zero, and the seeded generator refuses an interval with no width.", "The S-curve step became zero, so the remainder of a division by zero was taken at every sorted index and the error surfaced there.", "The percentile rule averages two neighbours, and with every NPV equal the average divided by their difference was undefined."]'::jsonb, 0, 'The lowest and the highest NPV were both 81.0464, so the width between them over 20 bins was zero; the repair tests the width first and sends every value to bin 0.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 3, 'An analyst runs a new field with every range at zero before any real run. What is that run for?', '["A check on the seed, since a zero run at seed 20260829 must reproduce the same 1000 NPVs that the default run with ranges draws.", "A measure of the field''s intrinsic uncertainty, because whatever spread survives with every range at zero is the spread the fixed inputs carry by themselves.", "A way to find the Low case P90 cheaply, because at zero range the three cases collapse onto the value the ranged run''s Low case will approach as iterations grow.", "A negative control: the sampler must give back the deterministic NPV and nothing else, and three cases that split would show it inventing spread."]'::jsonb, 3, 'On ISIALA the zero run must return 81.0464 in every slot; if it ever did not, no case from a ranged run could be believed.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 4, 'On the zero run ISIALA''s Low case P90 reads 81.0464 million USD. What does that say about the field?', '["That ISIALA has a 90 percent chance of being worth at least 81.0464 million USD, since a Low case P90 is an exceedance statement on the outcome.", "Nothing about the field''s chance of being worth that much; it says no range was given, and opex, royalty, tax, the decline and the 20 year life were never sampled anyway.", "That ISIALA carries no uncertainty at all, because setting the three ranges to zero also freezes every other input the Scenario Builder could have moved, opex and royalty included.", "That the field is robust, since the Low case and the High case agree and a narrow spread between them is the mark of a confident project."]'::jsonb, 1, 'Three equal cases are the absence of a belief, not a confident project; the Scenario Builder only ever samples price, capex and reserves, so zero on those means its own knobs are still.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 5, 'At 40 iterations the Scenario Builder as published returned an S-curve with nothing in it. What happened?', '["The run threw the same TypeError as a zero range run, because a short sample leaves most histogram bins empty and the empty bins break the count.", "The step, 40 divided by 50 rounded down, was zero, so the remainder test was not a number at every index and no point was kept, with no error and no warning.", "The curve kept one point, the first sorted value, because index 0 divided by any step leaves no remainder and the loop stopped after it.", "The engine refused to draw a curve below 50 iterations as a deliberate guard on short runs, and the panel reported the refusal as a blank chart instead of printing a message."]'::jsonb, 1, 'That is finding S5, a silent failure: the three cases, the emv and the histogram came back beside a blank chart. The repair floors the step at 1, so 40 iterations now give 40 S-curve points.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 6, 'Why is S5 described as worse than S4, although S4 stopped the run and S5 did not?', '["S5 corrupted the three NPV cases as well as the curve, while S4 only affected the histogram and left every number reported beside it intact.", "S5 was never repaired, so a short run still draws nothing today, while S4 was fixed in EC3-0 and a zero range run now returns the base case.", "S4 was caught by a published golden before release, while S5 slipped past every gate because no case in the goldens ran fewer than 50 iterations at all.", "S4 threw, so a user knew something broke; S5 returned plausible numbers beside an empty chart that looked like a rendering fault."]'::jsonb, 3, 'A silent failure carries no signal: the cases and emv were right and only the curve was missing. Both were repaired, and 40 iterations now give 40 points.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 7, 'ISIALA''s 1000 iteration S-curve ends at a probability of 98.0000. Where should a reader take the highest NPV of the run from?', '["From the sample itself, 149.3540 million USD, because the kept indices climb in steps of 20 and stop short of the top values, so the maximum is in the histogram but never plotted.", "From the last plotted point, which the downsample always places on the largest sorted value so that the curve spans the whole sample.", "From the High case P10 of 109.8980, which is the largest NPV the engine reports and so the value the curve''s top end represents.", "From the 98.0000 point plus the width of one histogram bin, which recovers the missing top of the curve from the bins beside it."]'::jsonb, 0, 'The lowest and highest values, 16.3054 and 149.3540, are read from the sample; the curve''s last point sits at 98.0000 because the kept indices climb in steps of 20 and the last one kept falls short of the end.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 8, 'The repair lets a 40 iteration run draw a curve. What does it not do?', '["Plot the forty points, since the repair only removes the error and the curve is still drawn from the histogram bins rather than the sorted values.", "Keep the seed, because the repaired step changes the order in which draws are consumed and a short run no longer reproduces from seed 20260829.", "Make a short run trustworthy: nothing in the output says the run was short, and the breakeven engine''s 90th percentile of breakeven price is 86.3529 at 100 iterations against 85.4380 at 20000.", "Report the three NPV cases, which below 50 iterations are withheld and replaced by the deterministic NPV until the run is long enough to rank."]'::jsonb, 2, 'Drawable is not reliable; a run of forty NPVs gives a forty step curve that looks like a distribution and carries no warning.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 9, 'In the published `mc_with_unreachable` breakeven tornado, every high side reads 0.0000. What does a high side of 0.0000 mean there?', '["That raising capex or opex to its 90th percentile leaves the breakeven price exactly where the base case put it, because the base already sits at the bracket top.", "That the three variables have no effect on the high side, since the tornado measures from the base breakeven and a bar with no length is a variable that cannot move it.", "That the engine rounded a small positive shift down to four decimals, because at a base breakeven of 498.0372 the remaining room below 500 is tiny.", "That the solve on that side found no price inside the 500 USD per bbl bracket, and the chart wrote the null as zero: the most dangerous direction, drawn as harmless."]'::jsonb, 3, 'Raise capex or opex to its 90th percentile, or drop efficiency to its 10th, and the breakeven leaves the bracket; that is finding B1, and it is still the engine''s output.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 10, 'Which of the edges this module examines is still the engine''s output after the EC3-0 repairs?', '["The one-sided tornado bar, finding B1: a side that cannot break even is still printed as 0.0000 with a swing of zero.", "The zero range run, finding S4, which still throws because the histogram repair was deferred to a later engines release after the course.", "The empty S-curve below 50 iterations, finding S5, which the repair only turned from a silent blank into a visible warning in the panel.", "The fit note''s wording, which still says a stated median is too near the P10 or the P90 when a belief is clamped."]'::jsonb, 0, 'S4 and S5 were repaired, and the fit note that used to say "too near the P10 / P90" (a P-label wrongly put on an input) now uses percentile words; B1 is the edge still open, and every high side of `mc_with_unreachable` reads 0.0000.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 11, 'The three bars of the `mc_with_unreachable` tornado come back as Total CAPEX, Annual OPEX, Prod. Efficiency, although efficiency''s low side of -26.2125 is far larger than opex''s -6.7689. Why that order?', '["The tornado sorts by the high side, and with all three high sides at 0.0000 it breaks the tie on the variable''s position in the belief list.", "Efficiency runs backwards, its low-price end coming from its 90th percentile, so its low side is subtracted from the swing and ranks it below opex.", "A null side gives a bar a swing of zero, every bar here has one, so the sort has nothing to sort on and the bars keep their input order.", "The sort is by the low side''s magnitude, and capex at -80.7218 leads while opex and efficiency are ranked on their stated medians instead."]'::jsonb, 2, 'In a tornado where the other bars had two sides, the variable that pushed the price out of the bracket would rank last, which is the reverse of its danger.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 12, 'Where in the breakeven engine''s output is the real answer for a tornado side drawn at 0.0000?', '["Nowhere, because the solver returns zero for an unreachable target and the chart only copies that value.", "In the sensitivity data, whose raw `low` and `high` prices keep the side that could not break even as null; only the tornado''s chart arrays turn it into 0.", "In the excluded count of the sample, which records 55 of 120 iterations and names, for each of them, the variable whose draw sent the breakeven price past the bracket.", "In the fit note appended to the insight, which the engine writes whenever a belief''s 90th percentile pushes a breakeven price past the top of the 500 USD per bbl bracket."]'::jsonb, 1, 'The engine keeps the information; read the raw pair before the bar, since null means no price inside the 500 USD per bbl bracket, not no movement.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 13, 'ISIALA''s narrow opex belief 16 / 17 / 26 has a shape ratio of 0.100000. What does the breakeven engine do with it?', '["Refuses the belief and asks for a wider one, since 0.100000 sits outside the band 0.381966 to 0.618034 that any triangular can reach.", "Reads the three numbers as a minimum, a mode and a maximum, because 16 / 17 / 26 makes a perfectly good triangle on that reading and needs no clamp.", "Switches the opex variable to a uniform distribution between the stated 10th and 90th percentiles, the nearest family that honours a median that low.", "Fits the most left-skewed triangular there is, 15.1886 / 15.1886 / 31.0000 with the mode at the minimum, sets `exact` to false and appends a note; it does not refuse the belief."]'::jsonb, 3, 'A triangular with its mode at the minimum gives a shape ratio of 0.381966, the lowest any triangular reaches, so the engine clamps there and says the median sits too near the 10th percentile.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 14, 'With the narrow opex belief, ISIALA''s base breakeven is 67.2301 USD per bbl while the median breakeven price is 73.1740. Why do the two describe different beliefs?', '["The base case and the tornado run at the stated median of 17, while the sample draws from the clamped triangle, which cannot put its median at 17 (finding EC3-5).", "Both run on the clamped triangle, and the gap between them is only the ordinary gap between one solve at the medians and the middle of a seeded sample of 5000 solves.", "The base case uses the fitted mode of 15.1886 and the sample uses the stated median of 17, so the two sit on opposite sides of the same belief.", "The base case is solved at the 10th percentile of every input and the median of the sample at the medians, as the insight''s note explains."]'::jsonb, 0, 'One screen mixes two opex beliefs: 67.2301 is the stated median''s answer, and the sample median barely moves from the 73.3297 of the belief that fits because the clamped triangle cannot put its median at 17.'),
  ('uncertainty', 'advanced', 'module', 'm04-edges-that-used-to-break', 15, 'With the narrow belief the Annual OPEX tornado bar reads -1.4602 low and 13.2707 high, against -5.8578 and 8.8730 on the belief 16 / 20 / 26. What does that bar follow?', '["The clamped triangle, swinging opex between its fitted minimum and maximum of 15.1886 and 31.0000 around the sample median of 73.1740 rather than around the base.", "The sample, taking the 10th and 90th percentiles of breakeven price under the narrow belief and measuring each of them from the base breakeven of 67.2301.", "The stated numbers: it swings opex between 16 and 26 around a base solved at 17, so a median near the bottom leaves little room below and much above.", "Nothing that changed, because a tornado moves one variable at a time and the other two beliefs are the same in both runs."]'::jsonb, 2, 'The tornado is part of the half of the result that reads the stated belief, the same half as the base of 67.2301, so read `exact` before quoting either beside the sample.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 1, 'NTEJE loses 123.9923 million USD at 12 percent and the screening engine reports its IRR as 1000.0000 percent. What is that number?', '["A root that lies beyond the clamp, the same gentle form as `irr_beyond_clamp`, whose true root of 9900 percent the engine cuts back to 1000.", "The Newton clamp: NTEJE''s NPV never changes sign at any rate, so no IRR exists, and the engine reports the 1000 percent bound (finding S1).", "The rate the first capex half earns in its first year, which the engine reports because the 20 percent decline pulls every later year toward a loss.", "The value the derivative guard returns when the slope of NTEJE''s NPV against the rate falls below its absolute threshold on the first iteration."]'::jsonb, 1, 'The guard asks only whether some year is negative and some positive; nothing checks that 1000 percent makes the NPV zero, and for NTEJE no rate does. The derivative guard''s return is 10.0000, not 1000.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 2, 'OKPOMA is worth 167.4389 million USD and also reports an IRR of 1000.0000 percent. What is that rate?', '["A real root past the clamp, cut back to 1000 in the same way the root of 9900 percent in `irr_beyond_clamp` is cut, because OKPOMA''s first year is already positive.", "The true rate OKPOMA earns, since a project that is cash positive before it has spent all its capex returns a rate without bound and the clamp only caps the display.", "The rate at which the 2029 cash flow of 57.8806 repays the second capex half, which the engine reports in place of the lifetime rate when the flows change sign twice.", "Not a root at all: OKPOMA''s only root is negative, its NPV stays positive at every rate from zero up, and Newton wandered upward from 10 percent until it stopped at the clamp."]'::jsonb, 3, 'Neither OKPOMA nor NTEJE is a root beyond the clamp; that form is `irr_beyond_clamp` at 9900 percent. The same 1000.0000 stands on a project that creates value and on one that destroys it.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 3, 'Three IRRs from the screening engine are return codes rather than solved rates. Which three, and what does each mean?', '["1000.0000 is a root past the clamp, 10.0000 is the discount rate echoed back, and 0.0000 is a project that breaks even exactly at a zero rate of return.", "Only 1000.0000 is a code, because `irr_known_21pct` shows the solver landing exactly on round roots and a round rate is therefore as likely to be a solve as a flag.", "1000.0000 is the clamp, 10.0000 is the starting guess handed back when the derivative guard fires, and 0.0000 is the answer when no year changes sign.", "1000.0000 and 0.0000 are the ceiling and the floor of the search, while 10.0000 is a genuine root that the tiny cash flow case shares with every scaled copy of it."]'::jsonb, 2, '`irr_tiny_cash_flows_derivative_guard` has a golden root of 21 and the engine returns 10.0000; `irr_beyond_clamp` has a root of 9900 and returns 1000.0000.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 4, 'ISIALA''s High scenario is worth 237.8860 million USD and reports an IRR of 0.0000 percent and a payback of 0.0000, beside a Base case IRR of 53.7148 percent. Why?', '["No year of the High case is negative, so the IRR guard finds no sign change and returns 0, and payback reads 0 because the first cumulative is already positive (finding EC3-2).", "The High case pushes the IRR past the 1000 percent clamp, and the engine resets an overflowing Newton iteration to zero instead of reporting the bound as it does for OKPOMA and for NTEJE.", "Scenario IRRs are not computed at all, and 0.0000 is the placeholder the scenario table fills for every case other than the Base, whose rate comes from the deterministic run.", "Cutting capex to 0.8 of the base removes the capex half the rate is measured against, so the IRR is undefined and printed as its default."]'::jsonb, 0, 'The Low scenario reports -3.5758 percent, so scenarios do solve an IRR; the High case''s maxExposure of 27.7707 is positive, which is the tell. The best of the three cases reads as the worst IRR.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 5, 'A portfolio screen ranks projects by IRR and passes any rate above a 12 percent hurdle. What happens to NTEJE, and what should be read first?', '["It ranks at the bottom, because the screen treats a rate sitting at the clamp as a missing value and places any missing IRR below every solved rate in the portfolio, whatever its NPV.", "It drops out, since a payback of 20.0000 years equals the project life and an IRR screen removes any project that never pays back before ranking the rest.", "It ranks at the top and passes on 1000.0000 percent while losing 123.9923 million USD; read the NPV, the final cumulative of -154.5906 and the sign of every year before the IRR.", "It ranks beside ISIALA, since a magnitude check that rejects rates above 100 percent treats both as flags and removes them from the ranking together."]'::jsonb, 2, 'A reader who rejects 1000.0000 as absurd has caught it; a screen that trusts the rate has put a value-destroying project first. ISIALA''s 53.7148 percent is a solved rate and no flag.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 6, 'OKPOMA''s cumulative is 9.2498 million USD after 2027 and -2.2287 after 2028, and its payback reads 0.0000. Why?', '["Every OKPOMA year is cash positive once royalty and tax are taken, so, as with ISIALA''s High scenario, the cumulative never crosses zero and payback falls back to its printed default of 0.0000.", "Payback is measured on cash flow discounted mid-year at OKPOMA''s 10 percent rate, and the discounted cumulative never drops below zero even though the undiscounted one does fall below zero in 2028.", "Payback counts from the last capex year, and the cumulative is already positive by the end of 2029, so no further years are needed after the spend ends.", "Payback is taken at the first year whose cumulative is non-negative and never revisited, so the second capex half taking the cumulative below zero in 2028 is ignored (finding EC3-1)."]'::jsonb, 3, 'OKPOMA''s 2028 net cash flow is -11.4786, so not every year is positive. A payback of 0.0000 beside a maxExposure of -2.2287 is the tell.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 7, 'ISIALA''s NPV is 81.0464 million USD discounted mid-year and 76.5817 discounted at year end, on the same rows at 12 percent. How are the two related?', '["By a fixed offset in million USD, the amount half a year of discounting adds to any project''s NPV at 12 percent, whatever the project''s size or sign.", "By a ratio of 1.058301, the square root of 1.12: shortening every exponent by one half multiplies each discounted term by the same factor.", "By the first year''s factor applied to the first year''s cash flow only, since every later year sits at a whole year exponent under both conventions.", "By a factor that depends on ISIALA''s decline and the timing of its capex, which is why the ratio is quoted for this field and would change on another."]'::jsonb, 1, '81.0464 over 76.5817 is 1.058301, equal to (1.12)^0.5; a gap in money would change with the project, while the ratio depends on nothing but the rate.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 8, 'NTEJE''s mid-year NPV at 12 percent is -123.9923 million USD. What happens to it if the same rows are discounted at year end?', '["It moves toward zero by the same ratio, -123.9923 divided by 1.058301, because the one factor scales a loss exactly as it scales a gain.", "It falls further below zero by the same money ISIALA''s NPV falls, because year end discounting always takes value away from a project.", "It stays at -123.9923, since the mid-year ratio only applies to a positive NPV and a losing project has no present value for the factor to scale.", "It grows more negative by the ratio 1.058301, since discounting later makes every loss look larger in present money and every gain smaller."]'::jsonb, 0, 'Every term is divided by the same (1.12)^0.5 at year end, so a losing project looks worse under mid-year by exactly the proportion a winning one looks better.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 9, 'Which ISIALA metrics are the same under mid-year and year-end discounting?', '["Only the payback of 3.2746 years, because the IRR is solved with mid-year factors and moves by the same ratio as the NPV when the convention changes.", "The NPV at the discount rate, since a ratio of 1.058301 is small enough to vanish once the result is rounded to the four decimals the engine prints.", "The peak exposure alone, because payback is read part way through a year and a half year shift in discounting moves where that crossing falls.", "The payback of 3.2746 years, the peak exposure of -44.6035 and the IRR of 53.7148 percent: the first two are undiscounted, and one factor on every term leaves the IRR''s root in place."]'::jsonb, 3, 'Both roots of `irr_two_roots`, 10 and 20 percent, are the year-end roots, and at a zero rate the conventions agree: the 10 year base case''s NPV at 0 percent is 908.4827, its final cumulative.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 10, 'A reviewer takes a year-end NPV from Petroleum Economics Studio and multiplies it by 1.058301 to set it beside the screening engine''s mid-year NPV for the same field. What is wrong?', '["Nothing, because the ratio depends only on the rate, and the rate is the one input the reviewer gave both engines for the field, so the product is the number the screening engine would print.", "The ratio holds only for identical rows at an identical rate, and the two engines build different ledgers, so the product is not the screening engine''s number.", "The factor runs the other way: the year-end NPV should be divided by 1.058301, since discounting at the middle of the year always lowers a positive NPV below its year-end value.", "The ratio must first be raised to the project life in years, because the half year shift compounds across every producing year of the ledger."]'::jsonb, 1, 'Mid-year NPV is 1.058301 times year-end NPV only on the same rows; the reviewer has the convention right and the rows wrong, since two tools almost never build identical rows.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 11, 'ISIALA''s screening NPV at 70 USD per bbl is 81.0464 million USD, yet its base breakeven price is 71.6277. How can both be right?', '["They cannot both be right, since a field worth 81.0464 million USD at 70 USD per bbl cannot need a price above 70 to reach zero on any honest ledger.", "The breakeven is discounted at year end and the NPV mid-year, and dividing by the ratio 1.058301 carries the one number onto the other.", "Each engine builds its own case: the analyzer puts all 180 million USD of capex in year 1, holds opex flat at 20 million USD a year and applies an efficiency of 0.91, and that case loses 6.5653 at 70.", "The 71.6277 is the median of a sample, which sits above the price a single deterministic case needs, so it lands above 70 where the base would not."]'::jsonb, 2, 'The quick form splits capex 90 and 90 over 2027 and 2028 with fixed and variable opex. The tax kinks show the capex move: tax switches on in year 1 only above 160.9994 USD per bbl.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 12, 'The breakeven analyzer reports 71.6277, 73.3297 and 96.5968 USD per bbl for ISIALA. Which of them is a percentile?', '["73.3297, the median of 5000 solves at seed 20260829; 71.6277 is one solve at the stated medians and 96.5968 is the breakeven to an NPV of 100 million USD.", "71.6277, because a solve with every input at its stated median is by construction the median of the breakeven price the sample would give.", "96.5968, the 90th percentile of breakeven price, since a hurdle of 100 million USD is how the analyzer encodes the upper tail of the three beliefs it was given.", "All three, since the analyzer reports only percentiles and lists the 10th, the median and the 90th percentile in that order."]'::jsonb, 0, 'The median of the sample sits above the base, so a solve at the medians is not the median of the solves; the 90th percentile of breakeven price is 85.5912.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 13, 'At the default seed ISIALA''s median breakeven price is 72.9245 at 1000 iterations, 73.3297 at 5000 and 73.0302 at 20000. What does the run tell a reader about accuracy?', '["That the 5000 run is the most accurate, because it is the count the course quotes as ISIALA''s headline and the default seed was chosen on it.", "That the median converges from above, so each longer run overstates the true median by less than the one before and 20000 is right to its last decimal.", "That the 20000 run has settled, because the engine stops iterating once two successive medians agree and reports the count at which they did.", "Nothing it states itself: the median does not settle in one direction, the 5000 run sits further from the 20000 run than the 1000 run does, and no standard error is reported."]'::jsonb, 3, 'Neither engine reports a standard error or a confidence band, or stops when an answer settles; 100 iterations and 20000 print their percentiles to the same four decimals.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 14, 'At 5000 iterations the median breakeven prices of seeds 1 to 10 run from 72.6338 to 73.1287, and the default seed''s 73.3297 sits outside all ten. What follows?', '["Nothing is wrong with seed 20260829: it drew a sample whose median lands high, and a seed buys reproducibility, not accuracy.", "The default seed is faulty, and its results should be replaced by the average of the ten ordinary seeds before any breakeven value is quoted.", "The default seed reproduces less reliably, since a reviewer rerunning seed 20260829 at 5000 iterations gets a median other than the one printed.", "The 5000 run excluded some iterations at the default seed, which pushed its median above the ten seeds whose samples kept every solve."]'::jsonb, 0, 'Seed 20260829 returns 73.3297 every time, and seed 7 at the same count returns 72.8475; the honest statement carries the seed, the count and the ten seed range of 0.4949.'),
  ('uncertainty', 'advanced', 'module', 'm05-numbers-to-distrust', 15, 'ISIALA''s Scenario Builder sample has a Low case P90 of 48.7439 million USD and a lowest NPV of 16.3054, while the Low scenario loses 72.1531. Why does no iteration come near the Low scenario?', '["1000 iterations are too few to reach the far tail, and a run of 20000 at the same seed would place a handful of iterations near the Low scenario''s loss of 72.1531 million USD.", "The ranges of plus or minus 20 percent are applied to the NPV rather than the inputs, so no iteration can fall more than a fifth below the base.", "Each value is drawn independently per year per array, so a whole life of low prices almost never occurs, and price, reserves and capex never move against the project together.", "The Low scenario scales fixed opex by 1.2, and the sampler would reach it if an opex range were typed, since opex is the input the three ranges leave out."]'::jsonb, 2, 'The Scenario Builder never samples opex, royalty or tax whatever ranges are typed, and the lowest draw of 16.3054 already sits far below a fifth off the base; independence narrows the spread.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Worked on ISIALA, in what order does the tier''s method take a graded probabilistic case?', '["The breakeven price first, since its base solve needs no seed, then the deterministic case, then the outcomes and the edges read together.", "The edges first, reading every fit and every tornado side before anything else, because a clamped fit would change each number that follows it.", "The outcomes first, since the Monte Carlo carries the deterministic case as its Best case P50 and so makes a separate deterministic run redundant.", "The deterministic case, then the Monte Carlo outcomes with their labels, then the breakeven price in percentile words, then every edge."]'::jsonb, 3, 'The deterministic case is not the Best case P50: ISIALA''s NPV is 81.0464 million USD and its Best case P50 is 81.1835, so each is run and written in its place.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 2, 'ISIALA''s deterministic case returns an IRR of 53.7148 percent and a payback of 3.2746 years. What check does the method ask before either is quoted?', '["That the IRR exceeds the 12 percent discount rate and the payback falls inside the capex years, which together confirm a solved rate.", "That the IRR is none of the return codes 1000.0000, 10.0000 or 0.0000, and that the cumulative crosses zero once, from -8.6381 in 2029 to 22.8165 in 2030, and stays positive.", "That the IRR and the NPV agree in sign and the payback is shorter than the 20 year life, the two conditions a return code always fails.", "That both reproduce under a second seed, since a deterministic metric that moved with the seed would have been drawn from the sample."]'::jsonb, 1, 'A clamp, a starting guess or a no sign change zero is not a rate, and a payback taken at a first crossing that later reverses is finding EC3-1; ISIALA passes both checks.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 3, 'An ISIALA result shows 109.8980 million USD under P90. What does the method say about it?', '["It is correct under the SPE PRMS reading, since P90 names the value that a 90 percent chance of success requires, and on an NPV that is the large one.", "It reflects the other percentile rule, since the breakeven rule that floors the index on the same sample moves the Low case to the upper end of the three values.", "Its labels are swapped: the Low case P90 holds the smallest NPV, 48.7439 under engine key `p10`, and 109.8980 is the High case P10 under key `p90`.", "It is right for engine key `p90`, and a P-label is only the engine key read aloud, so the two may be written interchangeably."]'::jsonb, 2, 'The panel that shipped before EC3-0 printed 109.8980 under "P90 (Conservative)". The engine key is a plain percentile and reading it aloud as a P-label is exactly the mistake examined.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 4, 'Why does the method quote ISIALA''s Low case P90 of 48.7439 million USD together with the screening engine that produced it?', '["On the same 1000 NPVs the breakeven rule puts the Low case at 48.8335, so the value depends on which percentile rule read the sample.", "Because the breakeven engine cannot read an NPV sample at all, so 48.7439 is the only Low case that exists for ISIALA.", "Because the screening engine draws from a different seed than the breakeven engine, and the seed decides which 1000 NPVs were drawn.", "Because 48.7439 is discounted at year end while the breakeven engine discounts mid-year, and the convention has to be named beside it."]'::jsonb, 0, 'Both engines default to seed 20260829 and the screening engine discounts mid-year; the difference of the two Low cases comes from averaging two neighbours against flooring the index.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 5, 'Which report of ISIALA''s breakeven price follows the method?', '["Target NPV 0, 5000 iterations, seed 20260829, 0 excluded; base 71.6277 at the stated medians; 10th percentile of breakeven price 62.1713, median 73.3297, 90th percentile of breakeven price 85.5912.", "Target NPV 0, 5000 iterations, seed 20260829; P90 breakeven 62.1713, P50 73.3297 and P10 85.5912, since a low price is the conservative case.", "Breakeven 73.3297 USD per bbl at the stated medians, with a range from 62.1713 to 85.5912 covering the whole sample of 5000 solves.", "Base 71.6277 and median 73.3297 averaged into one breakeven price, with its 10th and 90th percentile beside it and no seed needed."]'::jsonb, 0, 'A breakeven price is a quantity where more is worse and takes no P-label, so putting P90 on 62.1713 is the mistake examined; 71.6277 is one solve and 73.3297 the middle of the sample, and the 10th and 90th percentiles are not endpoints.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 6, 'What does reading the edges of ISIALA''s breakeven result find?', '["The opex fit is inexact, because a 10th percentile of 16 against a median of 20 sits too near the bottom of the band for any triangular to pass through.", "The efficiency bar has one side at 0.0000, since efficiency runs backwards and its high-price end cannot break even inside the 500 USD per bbl bracket.", "Every fit''s `exact` flag is true and every tornado bar has two sides, Total CAPEX -7.0202 and 9.4067 among them, with no side at 0.0000.", "Nothing worth writing down, since edges only matter on the published golden cases and a teaching field is built so that none of them can occur."]'::jsonb, 2, 'Opex 16 / 20 / 26 has a shape ratio of 0.400000, inside 0.381966 to 0.618034, and Prod. Efficiency reads -3.7306 and 5.0561; had a fit been inexact or a side zero, the answer would say so in words.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Every ISIALA value in an answer is correct. How can the answer still lose its marks?', '["It cannot, since the graded values are numbers, and a number correct to four decimals carries the whole of its mark.", "By writing a breakeven price with a P-label, by showing the High case first, or by quoting a median without its seed.", "By rounding, since each value must be quoted at the four decimals of the digest to be read as the correct value.", "By quoting the base breakeven at all, since 71.6277 is not sampled and only the three percentiles belong in a probabilistic answer."]'::jsonb, 1, 'The method keeps the base beside the percentiles and says which is which; the words are part of the answer, so the High case P10 of 109.8980 shown first is a wrong answer with right numbers.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 8, 'If ISIALA were rerun at seed 43 with every other setting the same, which results would not change?', '["Only the deterministic NPV, since every breakeven number the analyzer prints, the base included, is computed by solving on the sampled triangles.", "The Best case P50 of 81.1835, since the median of 1000 NPVs is stable and only the tails of the sample move with the seed.", "Every result, since the seed only reorders the draws, and a sorted sample of 1000 NPVs is the same whatever order its values were drawn from the generator in.", "The deterministic NPV of 81.0464, the base breakeven of 71.6277, the fits and the tornado sides, since none of them is drawn from the sample."]'::jsonb, 3, 'At seed 43 the Best case P50 is 79.0624 against 81.1835. The tornado moves one stated belief at a time with the others at their medians, so it is a solve and not a draw.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 9, 'Of the findings this tier names (S4, S5, B1, S1 and EC3-1), which describe the engine''s output after EC3-0?', '["Only B1, since EC3-0 repaired every screening engine finding along with the Monte Carlo seed, the IRR clamp and the payback taken at the first crossing among them.", "S4 and S5, since EC3-0 only rewrote the percentile labels on the two apps'' panels and left every numerical defect in both engines for the owner to decide.", "S1 alone, since B1 was repaired together with the fit note wording and EC3-1 was recorded as an observation rather than a defect.", "B1, S1 and EC3-1: a tornado side is still drawn at 0.0000, the IRR still reports its clamp, and payback is still not revisited; only S4 and S5 were repaired."]'::jsonb, 3, 'EC3-0 seeded the Monte Carlo and repaired S4 and S5; NTEJE still reports 1000.0000 percent, OKPOMA still reports a payback of 0.0000, and every high side of `mc_with_unreachable` still reads 0.0000.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 10, 'A question about PIA terms, working interest or an inflation basis for ISIALA comes up. Where does the tier hand it?', '["To Petroleum Economics Studio, the EC1 course''s engine, which carries those terms and discounts at year end on its own ledger.", "To the breakeven engine, which takes a fiscal regime beside its three beliefs and solves the price under that regime''s own terms.", "To the Scenario Builder''s quick form, whose TaxRoyalty terms can be switched to a PIA template before the Monte Carlo runs on it.", "Nowhere in the Suite, since screening is the last stage of the chain and fiscal detail is left to the operator''s own spreadsheets."]'::jsonb, 0, 'This tier is a screening tier with no PIA terms, no cost oil in the quick form, no working interest and no inflation basis; the quick form is TaxRoyalty only.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 11, 'ISIALA''s NPV reads 81.0464 or 76.5817 million USD, and its Low case P90 reads 48.7439 or 48.8335. Which statement is right?', '["One of each pair is wrong, and the method is to quote the larger NPV and the smaller Low case, which together make the conservative reading.", "The pairs are rounding differences, and at two decimals the two Low cases agree, which is the precision a decision needs anyway.", "Each is right for its own question: the NPVs differ by discounting convention on the same rows, the Low cases by percentile rule on the same sample.", "The first of each pair is the screening engine''s and the second comes from Petroleum Economics Studio, which discounts at year end and floors its index."]'::jsonb, 2, '81.0464 is mid-year and 76.5817 year end on identical rows, a ratio of 1.058301; 48.7439 averages two neighbours and 48.8335 floors the index. None is right without its method.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 12, 'ISIALA''s capex belief 150 / 180 / 220 is fitted to a triangle of 127.2260 / 168.6738 / 252.3607. What does that fit earn?', '["It widens the belief for caution, stretching the stated range outward so that the sample covers outcomes the estimator did not believe could occur.", "It honours the belief: the triangle passes back through 150, 180 and 220 at its 10th percentile, median and 90th percentile, where the old endpoints reading gave 164.4914, 182.5834 and 203.2668.", "It moves the base case, since the fitted mode of 168.6738 replaces 180 as the capex the breakeven engine solves its base breakeven at.", "It converts the belief to P-labels, reading 150 as the P90 capex because a lower cost is the conservative outcome for the project."]'::jsonb, 1, 'Reading the belief as minimum, mode and maximum deleted the tails. Capex is a parameter and takes percentile words, so calling 150 a P90 is the mistake examined; the base runs at the stated median of 180.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 13, 'How does a reader learn how far ISIALA''s median breakeven price would move under another seed?', '["From the engine''s standard error, printed beside each percentile, which states the half width of the confidence band.", "From the gap between the mean of 73.6242 and the median, which the analyzer uses as its measure of sampling noise.", "By doubling the iteration count, since the change between the two runs equals the seed to seed spread at the smaller count.", "By running other seeds, because neither engine reports it: ten seeds at 5000 iterations span a range of 0.4949 USD per bbl."]'::jsonb, 3, 'No engine in this tier says how far a percentile would move under another seed; the gap between mean and median is a skew, and the median does not settle as the count grows.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 14, 'What must stand beside ISIALA''s Best case P50 of 81.1835 million USD for the method to count it as a number?', '["The settings that produced it, 1000 iterations with price, capex and reserves each plus or minus 20 percent at seed 20260829, and the screening engine''s percentile rule.", "Its standard error and the iteration count at which the median settled, which the Scenario Builder reports beside each of its three cases.", "The deterministic NPV of 81.0464 as its benchmark, since a Best case P50 that differs from the deterministic value signals a sampling error.", "The breakeven price at the same seed, since the two engines share one sample and each NPV case is only valid beside its own price."]'::jsonb, 0, 'A probabilistic number without its label, its rule, its settings and its seed is not a number. The Best case P50 and the deterministic NPV differ by design, 81.1835 against 81.0464.'),
  ('uncertainty', 'advanced', 'module', 'm06-the-expert-reading', 15, 'The before-you-submit table has a Conventions check. What does passing it look like?', '["Exceedance labels written on the breakeven price, and the 10th percentile of every input read as its Low case.", "Mid-year discounting named, and one percentile rule per engine.", "The year-end NPV converted to mid-year with the ratio 1.058301, and the two percentile rules averaged into one.", "The seed and the iteration count written down, since those are the conventions a reviewer needs to reproduce a run."]'::jsonb, 1, 'Seed and iterations belong to the Settings check. An exceedance label on a breakeven price is exactly the mistake the Breakeven check catches, and a ratio converts nothing between two ledgers.'),
  ('uncertainty', 'advanced', 'final', null, 1, 'ISIALA''s Scenario Builder run returns 48.7439 under engine key `p10` and 109.8980 under `p90`. Which P-label does the Low case print, and which number does it hold?', '["P10, holding 48.7439, because a case takes its label from the engine key it reads and that key is the 10th percentile.", "P90, holding 109.8980, because the 90th percentile of the sorted NPVs is the value the label for ninety names.", "P90, holding 48.7439, the value that 90 percent of the 1000 sampled NPVs meet or exceed.", "P50, holding 81.1835, because a Low case in the Suite is the median of the draws that fall below the deterministic case."]'::jsonb, 2, 'Under the exceedance meaning P90 is the smallest of the three and reads the `p10` key, while the High case P10 reads `p90` and holds 109.8980.'),
  ('uncertainty', 'advanced', 'final', null, 2, 'A report quotes ISIALA''s breakeven price from 5000 iterations under the exceedance label for ninety. Why does the Suite refuse any P-label on that quantity?', '["More is worse for a price, so the label read by its definition names 62.1713 while the arithmetic habit names 85.5912, and nothing on the page says which was meant.", "Breakeven prices are solved by bisection rather than sampled, so the 5000 values carry no probability that a label could describe.", "The label is refused only because the breakeven engine floors its sorted index, and a floored index cannot carry an exceedance meaning.", "A breakeven is an input to the NPV rather than an outcome of it, so it takes the words capex and opex take."]'::jsonb, 0, 'One label would point at both ends of the band, 62.1713 and 85.5912 USD per bbl, while 10th percentile of breakeven price means 62.1713 to every reader.'),
  ('uncertainty', 'advanced', 'final', null, 3, 'A sheet gives ISIALA''s capex belief under P-labels, and an analyst must type the value it shows for ninety into the Breakeven Analyzer''s `p90` field. What goes wrong?', '["Nothing, because capex follows the same exceedance direction as NPV and the input field is keyed to match the sheet''s label, so the value can be copied across unchanged.", "The fit rejects a belief whose ends arrive reversed and asks for the three values again in ascending order before it runs.", "The field takes the minimum of the fitted triangle, so 127.2260 belongs there whatever label the sheet happens to use.", "Under the exceedance meaning that label names 150, the 10th percentile, while the field wants 220, so the ends of the fit swap."]'::jsonb, 3, 'The analyzer''s input keys are plain percentiles and a P-label carries no direction, which is why the convention writes 10th percentile of capex, 150, and 90th percentile of capex, 220.'),
  ('uncertainty', 'advanced', 'final', null, 4, 'A slide saved before EC3-0 shows an ISIALA card reading "P90 (Conservative)" over the largest of the three numbers. What is the right repair to that slide?', '["Swap the two outer numbers under the old words, so the card called conservative holds the smaller value again, which is what the old panel intended.", "Relabel the card as the High case P10 and keep its number, without expecting it to match 109.8980, because the old run was unseeded.", "Rerun the same inputs today and paste the seeded values over the old cards, since the repair made earlier runs reproducible too.", "Leave it alone, because the swap affected only the middle card and the Best case P50 of 81.1835 now reads correctly on every slide."]'::jsonb, 1, 'That card held the value only 10 percent of its sample met or exceeded. The old generator was unseeded, so the sample cannot be rebuilt and only the direction of the error can be fixed.'),
  ('uncertainty', 'advanced', 'final', null, 5, 'ISIALA''s run shows a deterministic NPV of 81.0464, a Best case P50 of 81.1835 and an emv of 80.1707. Which statement about the emv is right?', '["It is a third name for the P50, differing slightly only because the engine computes it from the histogram''s bin midpoints rather than the sorted values.", "It is the deterministic NPV rediscounted at the sampled prices, which is why it must fall between the Low case and the High case.", "It is the Best case under the floor rule, which is why it differs from the card by a fraction of a million USD.", "It is the plain mean of the 1000 NPVs, takes no P-label, and on this sample sits below both the Best case and the deterministic case."]'::jsonb, 3, 'The emv averages every sampled NPV. The floor rule''s median on the same sample is 81.1952, not 80.1707.'),
  ('uncertainty', 'advanced', 'final', null, 6, 'A board pack prints ISIALA''s scenario Low of -72.1531 under a P90 heading. Why is that wrong?', '["The scenario Low is one deterministic corner with every input bad in every year, while the P90 is a statistic of 1000 independent draws, 48.7439, and no iteration came near -72.1531.", "The number is right but belongs under P10, because the lowest case takes the lowest label on every quantity the Suite reports.", "The two are one quantity at different iteration counts, so -72.1531 is simply the P90 of a shorter run with fewer draws in it.", "The scenario Low applies a 30 percent move rather than 20 percent, so it is the P90 of a wider range the panel was not given."]'::jsonb, 0, 'The lowest of the 1000 NPVs is 16.3054. The scenario moves price and production to 0.8 and capex and fixed opex to 1.2 at once in every year, which independent yearly draws almost never do.'),
  ('uncertainty', 'advanced', 'final', null, 7, 'At the app''s settings, ISIALA''s 2027 oil volume of 1606000 bbl takes the first draw of seed 20260829, 0.936239. From what is it drawn, and where does it land?', '["From a triangular with its mode at 1606000 and its 10th and 90th percentiles at 0.8 and 1.2 times it, in the upper branch of the inverse CDF.", "Uniformly on [1606000, 1.2 x 1606000], since the reserves range is one sided and only ever scales a volume upward.", "Uniformly on [0.8 x 1606000, 1.2 x 1606000], landing near the top of that interval.", "From a draw on the field''s reserves total spread over the 20 years, so 2027 moves together with every later year."]'::jsonb, 2, 'Each value v with range r is drawn on [v(1 - r), v(1 + r)] with every point equally likely, and a draw of 0.936239 sits near the upper edge.'),
  ('uncertainty', 'advanced', 'final', null, 8, 'Suppose one iteration draws ISIALA''s first production year at the bottom of the reserves range, 0.8 of base. How much does that year''s variable cost column hold?', '["About 0.8 times 20.8780 million USD, because the reserves range scales the volume and variable opex is that volume times 13 USD per bbl.", "20.8780 million USD, the base-volume money, because variable opex was fixed when the quick inputs were expanded and is never sampled.", "A fresh uniform draw around 20.8780 million USD, taken right after the capex draw of the same iteration.", "Nothing for that year, because the sampler removes opex from any year whose drawn volume falls below its base value."]'::jsonb, 1, 'Opex, royalty, tax and the discount rate keep their case values in every iteration (EC3-7), so a low volume draw saves no variable opex.'),
  ('uncertainty', 'advanced', 'final', null, 9, 'Seed 43 gives ISIALA a Best case P50 of 79.0624, and the default seed gives 81.1835, nearer the deterministic 81.0464. Which reading is right?', '["The default seed is the accurate one, since it was chosen so that the sample reproduces the deterministic case to within rounding at the app''s settings.", "Seed 43 is the more accurate one, since any seed away from the shared default avoids the bias the default carries into both engines.", "Both are reproducible samples of 1000 and neither is more accurate, so preferring the default for sitting nearer 81.0464 is seed shopping.", "Neither is usable, because a working sampler returns one median at every seed and a gap between seeds is a defect."]'::jsonb, 2, 'A seed buys reproducibility, not accuracy. The gap between the two medians is part of the uncertainty, so fix the seed before the first run and record it.'),
  ('uncertainty', 'advanced', 'final', null, 10, 'The Scenario Builder and the Breakeven Analyzer both default to seed 20260829, and both begin with the draw 0.936239. What links their two samples?', '["Nothing: the Scenario Builder spends that draw on ISIALA''s 2027 oil volume, and the breakeven engine turns it into a capex of 226.5205 million USD.", "Their iterations, which share one random state, so a high NPV in one lines up with a low breakeven price in the other, iteration for iteration across the two apps.", "Their medians, which the shared seed forces to agree once the NPV is turned into a price through the mid-year ratio of 1.058301 at 12 percent.", "Their exclusions, since an iteration the breakeven engine drops is dropped from the Scenario Builder''s 1000 NPVs as well."]'::jsonb, 0, 'The breakeven engine takes three draws per iteration, capex, opex and efficiency, through a triangular inverse CDF, so samples from the two apps at one seed have nothing to do with each other.'),
  ('uncertainty', 'advanced', 'final', null, 11, 'ISIALA''s histogram at seed 20260829 has its tallest bin, the ninth, at 114, while the Best case P50 of 81.1835 falls in the tenth, holding 94. What does the tallest bin tell you?', '["The most likely NPV, which a decision should prefer to the median because the mode is where the draws concentrate most densely across the 1000 iterations.", "Two populations in the field, since a dip between tall bins means the draws came from two regimes of the model that the ranges switch between from one year to the next.", "The Low case P90, since the engine reads each of its cases from an edge of the bin that holds the most draws.", "Little: its bins are 6.6524 wide between this sample''s own lowest and highest values, and a slightly different width would merge or split the peaks."]'::jsonb, 3, 'The model has one field and three uniform ranges and nothing that makes two peaks. The cases come from the sorted sample, never from a bin edge.'),
  ('uncertainty', 'advanced', 'final', null, 12, 'ISIALA''s 1000 iteration S-curve ends at probability 98. What becomes of its highest NPV, 149.3540?', '["It is the point plotted at 98, because the curve rescales its axis so that the last point is always the maximum of the sample, whatever the step.", "It is in the sample and the histogram but never drawn on the curve, which keeps one sorted value in every 20 and stops short of the end.", "It was excluded from the sample as an outlier before sorting, which is why the curve stops short of 100 percent and the histogram ends below it.", "It sits at probability 100 on a point the chart hides under its axis frame, so it is plotted but not visible."]'::jsonb, 1, 'The step is floor(1000 / 50) = 20, so the kept indices stop at probability 98.0000 (EC3-6). Read the extremes from the lowest and highest values, 16.3054 and 149.3540.'),
  ('uncertainty', 'advanced', 'final', null, 13, 'A golden case switches off everything but price uncertainty (`mc_seed3_price_only`). Where in the random stream do its price values come from?', '["They are unchanged from a full run, because each array keeps its own position in the stream whether or not an earlier range is sampled.", "They are drawn twice as wide, since the sampler moves the unused reserves and capex width onto the one range still set.", "They are replaced by the deterministic prices, since the sampler draws nothing until at least two ranges are set.", "They take stream positions the volume draws would have used, since a falsy range consumes no draw."]'::jsonb, 3, 'The seed fixes the stream, not which value each draw goes to. ISIALA''s gas draws still consume positions although gas volume is 0, because their range is not falsy.'),
  ('uncertainty', 'advanced', 'final', null, 14, 'Why can ISIALA''s Low case P90 of 48.7439 not be found anywhere in the exported sorted sample of 1000 NPVs?', '["The card rounds its sampled value to four decimals while the export keeps full precision, so an exact search finds no match.", "The card is stale from before EC3-0, when an unseeded sampler wrote a different sample from the one now exported.", "n x 0.1 = 100 is whole on an even length, so the screening rule averages two neighbours, and the upper one is 48.8335.", "The rule interpolates linearly across the whole bin that holds the 10th percentile, so its answer falls between two bin edges."]'::jsonb, 2, 'Under its own rule the card is right. The floor rule reads the single value 48.8335 on the same sample, a difference of -0.0896.'),
  ('uncertainty', 'advanced', 'final', null, 15, 'Every difference between the averaging rule and the floor rule on ISIALA''s 1000 NPVs is negative: -0.0896, -0.0116 and -0.0056. Why can none be positive on this sample?', '["With n x q whole, the averaging rule blends the value at the index with the one before it, while the floor rule takes the value at the index, the upper of the two.", "The floor rule rounds its index down, so it takes the lower of the two neighbours and always reads below the average.", "The NPVs are skewed to the right, so any rule that avoids averaging reads higher than the average in both tails and at the middle.", "The averaging rule weights each value by its histogram count, which pulls every case toward the tallest bin below the median."]'::jsonb, 0, 'The floor applies to the index, not to the answer. On an NPV it leans toward the good end, so a reader who takes the floor rule as the cautious one has the direction backwards.'),
  ('uncertainty', 'advanced', 'final', null, 16, 'Two Scenario Builder runs of one field differ only in iteration count, 1000 and an odd number. How is the Best case read in each?', '["Both are averages, because the rule always blends the two values nearest the middle whatever the iteration count happens to be.", "At 1000 it is the mean of the two middle values; on the odd count it is a single sorted value, and nothing on the panel says which branch ran.", "Both take the single value at floor(q n), since the Scenario Builder switches to the breakeven engine''s rule on any count other than 1000, to keep each case a member of the sample.", "The odd count averages the three values around the middle position, and the panel marks that run as interpolated."]'::jsonb, 1, 'On an odd length n x 0.5 is never whole, so no case is averaged. At 1000 every case is, and the middle one reads 81.1835.'),
  ('uncertainty', 'advanced', 'final', null, 17, 'Ten alternative seeds put ISIALA''s middle breakeven between 72.6338 and 73.1287 USD per bbl, yet the shipped default lands on 73.3297. Should the default be distrusted?', '["It is biased, and the default should be moved to a seed whose median falls inside the span of the ten seeds.", "It is the most accurate of the eleven, because the default seed is the one the published goldens were calibrated against.", "It exposes a defect in the floor rule, since a median read from one sorted value should never leave the span of ten others.", "Nothing is wrong with it: it drew a sample whose median lands high, and it repeats that edge exactly on every run."]'::jsonb, 3, 'The ten medians have a range of 0.4949 USD per bbl, and ten seeds are not the whole range either: an eleventh could land outside both ends.'),
  ('uncertainty', 'advanced', 'final', null, 18, 'Run length is raised from 1000 to 5000 to 20000 and the middle breakeven goes 72.9245, 73.3297, 73.0302. What does that sequence teach about sample size?', '["The 5000 run is faulty, because a percentile must approach its limit steadily as the iteration count grows.", "The 20000 value is the true median, so each shorter run''s error is exactly its difference from 73.0302.", "More iterations shrink the typical wobble but promise nothing about one run: here the 1000 iteration median sits closer to the 20000 value than the 5000 does.", "The run had converged by 1000 iterations, and the later changes are floating point noise in the fourth decimal place."]'::jsonb, 2, 'The 20000 iteration run is one more sample from one seed, and the engine gives no standard error, no confidence interval and no convergence check.'),
  ('uncertainty', 'advanced', 'final', null, 19, 'On ISIALA, order these from smallest to largest: the gap between the two percentile rules at the median, the change in the Best case P50 from seed 20260829 to seed 43, and the gap between the mid-year and year-end NPV.', '["The seed change, then the rule gap, then the convention gap, since a seed only reorders draws that the two rules then read differently.", "The rule gap of -0.0116, then the seed change from 81.1835 to 79.0624, then the convention gap from 81.0464 to 76.5817.", "The rule gap, then the convention gap, then the seed change, since mid-year discounting scales the NPV by only 1.058301.", "The convention gap, then the rule gap, then the seed change, since mid-year and year-end differ by no more than half a year."]'::jsonb, 1, 'The choice of rule is the smallest of the three and the only one that changes nothing about the sample, while mid-year multiplies the whole NPV by 1.058301.'),
  ('uncertainty', 'advanced', 'final', null, 20, 'ISIALA with every range at zero for 30 iterations returns 81.0464 as its Low case P90, Best case P50, High case P10, emv and deterministic NPV. What does that Low case P90 say?', '["That no range was given: the run is the sampler''s negative control and says nothing about a 90 percent chance of ISIALA being worth that much.", "That ISIALA carries no downside, since a Low case equal to the deterministic NPV means the field is certain at those settings.", "That the sampler failed silently, because a working Monte Carlo must spread its three cases even when the ranges are zero.", "That the run hit finding S4 again, since three equal cases are what the old histogram fault produced in the moment before it threw its TypeError."]'::jsonb, 0, 'Opex, royalty and tax are never sampled at any setting, so zero on the three ranges only means the sampler''s own knobs are still. Bin 0 holds 30 of 30.'),
  ('uncertainty', 'advanced', 'final', null, 21, 'Why did the published engine throw on a Scenario Builder run with every range at zero (finding S4)?', '["Newton''s IRR iteration met a zero derivative on identical cash flows in every iteration and threw rather than return its starting guess.", "The S-curve''s step divided by zero, so its remainder test threw on the first sorted index it tried to keep.", "The bin width was the range over 20, which was zero, so zero over zero gave a bin index that is not a number and counting into it threw.", "The percentile rule averaged two identical values and then divided by their difference to find a weight."]'::jsonb, 2, 'The repair tests the width first and sends every value to the first bin. The zero S-curve step of S5 never threw; it returned an empty curve.'),
  ('uncertainty', 'advanced', 'final', null, 22, 'What did the published Scenario Builder return for its S-curve at 40 iterations (finding S5)?', '["A single point at probability 100, because a step of zero kept only the last sorted value of the run.", "A TypeError, the same fault as a zero-range run, caught by the panel and shown to the user as an error banner.", "Forty points, as it does now, but at probabilities scaled to a 1000 iteration axis so that they bunched at the left.", "An empty array with no error, because floor(40 / 50) is zero and the remainder by zero failed every test."]'::jsonb, 3, 'The cases, the emv and the histogram came back beside a blank chart, which looked like a rendering fault. The repair floors the step at 1, giving 40 points.'),
  ('uncertainty', 'advanced', 'final', null, 23, 'On `mc_with_unreachable` the right-hand end of each tornado bar is printed as 0.0000. How should an analyst interpret that blank?', '["The variable cannot raise the breakeven price at all, so the three bars show only downside relief and are ranked from the largest low side to the smallest.", "The most dangerous direction: that end has no breakeven price below 500 USD per bbl, the solver returns null, and the chart writes it as zero.", "The high side solved exactly at the base breakeven of 498.0372, so moving that variable toward its bad end leaves the breakeven price where the base put it.", "The side was skipped to save solves once 55 of 120 iterations had already been excluded from the sample."]'::jsonb, 1, 'Each null side gives a swing of zero, so the sort has nothing to sort on and efficiency''s -26.2125 ranks below opex''s -6.7689 (B1). The raw low and high in the sensitivity data keep the null.'),
  ('uncertainty', 'advanced', 'final', null, 24, 'Three published faults were repaired in EC3-0 and one was left in place. Which one would a user still meet?', '["The error thrown on a Monte Carlo with every range at zero, finding S4, which the histogram still raises on a zero width.", "The empty S-curve below fifty iterations, finding S5, which still returns no points at all on a run of 40 iterations.", "A tornado side that cannot break even inside the bracket, drawn at 0.0000 (B1).", "The fit note that described a clamped belief in P-labels, which the Breakeven Analyzer still shows beside the insight."]'::jsonb, 2, 'S4, S5 and the fit note words are repaired: zero ranges now return 81.0464 in all three cases and 40 iterations give 40 points. Every high side of `mc_with_unreachable` still reads 0.0000.'),
  ('uncertainty', 'advanced', 'final', null, 25, 'ISIALA with the narrow opex belief 16 / 17 / 26 reports a base breakeven of 67.2301 and a median breakeven price of 73.1740. Why should the two not be quoted as one belief?', '["The base and the tornado use the stated median of 17, while the sample draws from the clamped triangle 15.1886 / 15.1886 / 31.0000, whose median is not 17.", "The base is discounted at year end and the sample at mid-year, so the two differ by the ratio between the conventions.", "The median comes from the averaging rule and the base from the floor rule, so their gap is the rule difference at 5000 iterations.", "The belief was refused and replaced by 16 / 20 / 26 for the sample, while the base kept the values that were typed."]'::jsonb, 0, 'Its shape ratio of 0.100000 lies outside 0.381966 to 0.618034, so the fit clamps, `exact` reads false and the insight carries the note (EC3-5). Read `exact` before quoting either number.'),
  ('uncertainty', 'advanced', 'final', null, 26, 'What does the breakeven engine do with a belief whose shape ratio falls outside 0.381966 to 0.618034?', '["It refuses the belief and asks for one whose median sits nearer the middle of the stated 10th and 90th percentiles.", "It switches to a uniform distribution between the stated 10th and 90th percentiles, the shape the Scenario Builder uses.", "It reads the three stated values as the minimum, mode and maximum, which always make a valid triangle.", "It fits the most skewed triangle on that side, sets `exact` to false, appends a note and carries on."]'::jsonb, 3, 'It never refuses. The old endpoints reading accepted every belief silently while cutting its tails: capex 150 / 180 / 220 came back as 164.4914, 182.5834 and 203.2668.'),
  ('uncertainty', 'advanced', 'final', null, 27, 'A screening run on NTEJE prints a rate of return of 1000.0000 percent beside an NPV of -123.9923. How much of that rate is real?', '["A true root beyond the clamp, the form of `irr_beyond_clamp`, which the engine caps and reports at 1000 percent in place of the higher rate the cash flow earns.", "The Newton clamp: no rate makes NTEJE''s NPV zero, and the engine reports where the iteration stopped without checking the NPV there.", "A rate the cash flow earns in its first years, before the second capex half is spent and the NPV turns negative.", "The code the engine prints for a project that never pays back, whenever its payback reads the project life of 20."]'::jsonb, 1, '`irr_beyond_clamp` has a real root at 9900 percent; NTEJE has none. A reader who ranks projects by IRR puts NTEJE at the top (S1), and `irr_all_negative` never pays back yet reports 0, so 1000 is no never-pays-back code.'),
  ('uncertainty', 'advanced', 'final', null, 28, 'OKPOMA, valued at 167.4389 million USD, prints an internal rate of 1000.0000 as well. Where did its number come from?', '["Its only IRR root is negative, so Newton wandered upward from its 10 percent start and stopped at the clamp, which is no root at all.", "Its root lies past the clamp, the gentle form, so the project truly earns more than 1000 percent and the clamp understates it, as in `irr_beyond_clamp`.", "The rate is right, because a first year already cash positive makes the IRR unbounded and 1000 is how the engine says so.", "It is the starting guess returned by the derivative guard, finding S2, since OKPOMA''s final years carry tiny cash flows."]'::jsonb, 0, 'Neither OKPOMA nor NTEJE is a root past the clamp; that form is `irr_beyond_clamp` at 9900. The guard asks whether the years differ in sign, never whether the last guess makes NPV zero, and S2 returns 10, not 1000.'),
  ('uncertainty', 'advanced', 'final', null, 29, 'OKPOMA reports a payback of 0.0000 beside a peak exposure of -2.2287. What produces that pair?', '["Payback is measured on discounted cash flow and peak exposure on undiscounted cash flow, so the two describe different ledgers.", "The engine sets payback to zero whenever the IRR reports its 1000 percent clamp, and peak exposure is not affected by that rule.", "The 2028 loss falls within the first half year of mid-year discounting, so a payback under one year rounds to 0.0000.", "The cumulative is 9.2498 after 2027, so payback is taken at index 0, and the second capex half then takes it to -2.2287 in 2028 without the payback being revisited."]'::jsonb, 3, 'Payback is the first index at which the cumulative is non-negative and is never looked at again (EC3-1). A payback of 0 beside a negative peak exposure is the tell.'),
  ('uncertainty', 'advanced', 'final', null, 30, 'ISIALA''s mid-year NPV is 81.0464, and the same rows discounted at year end give 76.5817. Which statement holds?', '["The ratio depends on when capex falls, so ISIALA''s 50/50 split sets it and a field with all capex in year 1 would give another.", "The gap is upside that mid-year discounting finds, so a year-end tool understates ISIALA''s value on the same rows.", "Their ratio is 1.058301, the square root of 1.12, set by the rate alone; payback, peak exposure and the IRR are unchanged.", "Payback shortens by half a year under mid-year discounting, while the fixed ratio holds only for a positive NPV."]'::jsonb, 2, 'Every exponent shortens by one half, so every term carries the same factor, and a losing project looks worse by exactly the same proportion.'),
  ('uncertainty', 'advanced', 'final', null, 31, 'At 70 USD per bbl one Suite tool values ISIALA at 81.0464 million USD while another says it only breaks even at 71.6277. Is one of them wrong?', '["The breakeven engine discounts at year end, so dividing its price by 1.058301 recovers the screening case''s breakeven below 70.", "They describe two cases: the breakeven engine puts all 180 million USD of capex in year 1, holds opex flat at 20 and applies an efficiency of 0.91, losing 6.5653 at 70.", "The breakeven is the median of 5000 solves, which always sits above the deterministic case, so the gap is sampling noise.", "One of them is wrong, since an NPV of 81.0464 at 70 proves the breakeven lies below 70 and the analyzer has a defect."]'::jsonb, 1, 'The screening engine never solves for its own breakeven, though its sweep at 0.7 of price gives -17.3893. The mid-year ratio scales an NPV on identical rows and is no factor between two prices.'),
  ('uncertainty', 'advanced', 'final', null, 32, 'None of ISIALA''s 1000 sampled NPVs loses money, yet its Low scenario loses 72.1531 million USD. What can a reader conclude about the chance of that outcome?', '["Nothing from this sample: independent yearly draws almost never put a whole life at the bottom together, so the distribution cannot price a correlated outcome.", "ISIALA''s chance of it is below one in 1000, since 1000 iterations without a single loss bound that chance from above.", "It is about 10 percent, since the Low scenario sits below the Low case P90 and 10 percent of the sample lies below that case.", "It equals the share of iterations below 16.3054, which the S-curve plots at probability 0.0000 and so reads as none."]'::jsonb, 0, 'Opex, royalty and tax are never sampled and no draw leans on another. The missing risk is correlated, structural or never modelled.'),
  ('uncertainty', 'advanced', 'final', null, 33, 'OKPOMA''s 2046 row loses 0.5576 million USD on gross revenue of 4.4603. What happens to that year in every sampled iteration?', '["It is dropped from any iteration whose sampled volume makes its net cash flow negative, which is the engine''s economic limit.", "It is kept only in iterations whose price draw sits below base, since a higher draw makes the year profitable and uninformative.", "It is produced and charged, because the screening engine has no economic limit and no range reaches the 20 year life.", "It is cut from every iteration, because the quick form ends the life at the last year of positive net cash flow."]'::jsonb, 2, 'Its opex of 4.5718 exceeds its revenue, and the quick form fixes the life, the decline, the flat price and the TaxRoyalty terms beyond any range.'),
  ('uncertainty', 'advanced', 'final', null, 34, 'Working the capstone order on ISIALA, what check does the tier ask for on the deterministic IRR of 53.7148 percent before it is quoted?', '["That it exceeds the 12 percent discount rate, which is what confirms that the Newton iteration converged onto a root.", "That it matches the Monte Carlo''s Best case P50 once that NPV is converted to a rate through the mid-year ratio.", "That it lies between the Low and High scenario IRRs of -3.5758 and 0.0000 percent, as a base case must.", "That it is not 1000.0000, 10.0000 or 0.0000, the values the solver returns when it did not solve."]'::jsonb, 3, 'The High scenario''s 0.0000 is the no-sign-change return (EC3-2), and ISIALA''s cumulative crosses zero once, from -8.6381 in 2029 to 22.8165 in 2030, so its payback of 3.2746 is no re-crossing either.'),
  ('uncertainty', 'advanced', 'final', null, 35, 'Every ISIALA value in an answer is correct. Which of these would still lose it marks under the tier''s order of work?', '["Showing the High case first, putting a P-label on a breakeven price, or quoting a median without its seed.", "Leaving out the histogram''s bin counts, since the reading grades the shape of the sample before any of its cases.", "Quoting money in million USD instead of converting every value to USD, which the units check asks for.", "Leaving out the year-end NPV of 76.5817, since the reading requires both discounting conventions side by side."]'::jsonb, 0, 'The careful mistake is the right numbers under the wrong words. The settings check wants the iterations, ranges, target and seed beside every sampled number.'),
  ('uncertainty', 'advanced', 'final', null, 36, 'ISIALA''s tornado reads Total CAPEX -7.0202 and 9.4067, Annual OPEX -5.8578 and 8.8730, Prod. Efficiency -3.7306 and 5.0561, and every fit is exact. Why must an answer still say it read them?', '["The tornado sides are percentiles of the 5000 iteration sample, so they must be quoted with the seed that produced them and its iteration count.", "An inexact fit or a side at 0.0000 changes what the base and the bars mean, so the answer states in words that neither occurred.", "A bar with two sides means some iteration was excluded, and the answer must count those exclusions beside the percentiles of breakeven price.", "Efficiency''s high side being smaller than capex''s means its fit clamped, and a clamped fit has to be named."]'::jsonb, 1, 'A null side is drawn at 0.0000 (B1) and a clamp splits the base from the sample (EC3-5). On ISIALA no side is 0.0000 and the capex, opex and efficiency fits are all true.'),
  ('uncertainty', 'advanced', 'final', null, 37, 'Which of ISIALA''s reported numbers would move if the whole reading were rerun at another seed?', '["Only the emv, since the three cases and three percentiles are read from fixed sorted positions, and a position does not depend on which draw landed in it.", "Every number including the base breakeven of 71.6277, since the breakeven engine solves its base case from the first draw of each iteration rather than the stated medians.", "The three NPV cases, the emv and the three breakeven percentiles, while the deterministic NPV of 81.0464 and the base breakeven of 71.6277 stay put.", "None of them, since the repaired engines fix the seed at 20260829 and ignore any other seed they are passed."]'::jsonb, 2, 'A seed moves the sample: seed 43 gives a Best case P50 of 79.0624 and seed 7 a median breakeven price of 72.8475. The deterministic case and the base solve at the stated medians take no draws.'),
  ('uncertainty', 'advanced', 'final', null, 38, 'A reader takes the value at height 90 on ISIALA''s Scenario Builder S-curve and prints it as the P90. Which pair of errors has been made?', '["None in the label, since height 90 is the Low case P90, but the curve plots averages where the card reads a single value from the sorted NPVs, which is why the two disagree.", "The curve stops at 98, so height 90 is extrapolated, and the extrapolation borrows the breakeven engine''s (i + 1) / n axis.", "The axis counts exceedance, so height 90 is the Low case, and the curve is drawn from bin edges rather than from the sorted sample of 1000 NPVs that the three cards read.", "Height 90 is the value 90 percent of the sample falls below, the High case P10, and the curve reads a single sorted value, 109.9036 against the card''s 109.8980."]'::jsonb, 3, 'The y axis counts from below, so a label taken straight off it swaps the cases the way the old cards did, and the curve uses the rule the cards do not (EC3-6).'),
  ('uncertainty', 'advanced', 'final', null, 39, 'In `mc_with_unreachable`, 55 of 120 iterations are excluded and the 10th percentile of breakeven price reads 397.3404. Which statement about that number is right?', '["It is the mean of two neighbouring prices, since the breakeven engine switches to the averaging rule once exclusions leave an odd count.", "It is a price one surviving iteration produced, read by the floor rule, and it describes only iterations that broke even below 500 USD per bbl.", "It already counts every excluded iteration as a price of 500 USD per bbl at the top of the bracket, so a 10th percentile over all 120 iterations would sit lower still.", "It is also the tornado''s low end for capex, since the bars and the percentiles are read from the same excluded sample of surviving iterations."]'::jsonb, 1, 'The floor rule has one branch at any surviving count. On the same case every tornado high side reads 0.0000 (B1), so neither the percentiles nor the bars see the iterations that never broke even.'),
  ('uncertainty', 'advanced', 'final', null, 40, 'A memo pairs ISIALA''s Low case P90 of 48.7439 with its 90th percentile of breakeven price, 85.5912 USD per bbl, as the downside of one run. What is wrong?', '["They come from different engines and samples, uniform ranges on price, capex and reserves against fitted triangles on capex, opex and efficiency, so no iteration links them.", "Nothing, since both are 90 percent statements and the shared seed of 20260829 makes them come from the same iterations.", "The price should be the 10th percentile of breakeven price, 62.1713, because a low NPV pairs with the lowest breakeven.", "They are one run, but the NPV has to be restated at year end with 1.058301 before it can sit beside a price."]'::jsonb, 0, 'At one seed the first draw, 0.936239, is an oil volume in one app and a capex of 226.5205 million USD in the other. A shared label or pairing invents a link.'),
  ('uncertainty', 'advanced', 'final', null, 41, 'An analyst widens ISIALA''s price, capex and reserves ranges until the Low case P90 looks cautious enough, then calls it a risk assessment. What does the tier say?', '["It becomes sound once the ranges pass 30 percent, the width the sensitivity sweep uses, because the two tools then agree.", "It becomes sound if the seed is changed as well, since a new seed removes the independence between years that narrows the sample and lets the tails reach further.", "It is sound, because the Low case P90 then approaches the scenario Low of -72.1531, and that scenario is the probability weighted downside of the whole field.", "A wider uniform range only fattens independent noise; the missing risk is correlated across years, sits in opex, royalty and tax, or is never modelled."]'::jsonb, 3, 'Independence is why 48.7439 sits far above -72.1531 (EC3-7), and no range reaches the 20 year life, the decline or the TaxRoyalty terms.'),
  ('uncertainty', 'advanced', 'final', null, 42, 'Which sentence reports ISIALA''s Low case the way the tier requires?', '["P90 (Conservative) 48.7439 million USD at 1000 iterations and seed 20260829, the cautious card of the three.", "A P10 of 48.7439, since the engine returned it under `p10` and a key names its own label, from 1000 draws at seed 20260829.", "Low case P90 48.7439 million USD, engine key `p10`, averaging rule, 1000 iterations, price, capex and reserves each plus or minus 20 percent, seed 20260829.", "A 90 percent chance of at least 48.8335 million USD, the single sorted value at index 100, with the ranges and seed recorded beside it."]'::jsonb, 2, 'The Low case prints P90 while reading `p10`, so the version printed as P10 reads the key aloud as a label, which is the mistake. 48.8335 is the floor rule''s reading, and Conservative is not a word of the convention.');
